// Generated by scripts/build.py; edit JSON sources only.
window.UKPPPG_BANK = {"schemaVersion":1,"codes":{"P.1":"Merancang dan memfasilitasi pengalaman belajar Murid yang mendorong pemahaman konseptual, penerapan kontekstual, dan refleksi bermakna terhadap proses pembelajaran","P.2":"Melaksanakan pembelajaran yang responsif terhadap keragaman latar belakang, kebutuhan, dan potensi Murid melalui berbagai model pembelajaran","P.3":"Menciptakan proses pembelajaran yang berkesadaran, bermakna, dan menggembirakan","P.4":"Mengintegrasikan teknologi informasi dan komunikasi secara kritis dan kreatif dalam pembelajaran untuk memperluas akses, memperdalam pemahaman, dan mendukung literasi digital Murid","P.5":"Menerapkan strategi pembelajaran atau pembimbingan yang sesuai karakteristik Murid dengan memanfaatkan sumber belajar dan mempertimbangkan potensi lingkungan dan kearifan lokal","P.6":"Melaksanakan asesmen untuk mengetahui kebutuhan belajar, memberikan umpan balik, dan mengukur hasil belajar Murid secara berkesinambungan dan reflektif","K.1":"Menampilkan perilaku etis dan keteladanan yang mencerminkan kematangan spiritual, moral, dan emosional berdasarkan Ketuhanan Yang Maha Esa dan nilai-nilai keberagaman","K.2":"Melakukan refleksi diri secara berkesinambungan, mengembangkan pola pikir bertumbuh, serta belajar sepanjang hayat untuk peningkatan kualitas diri","K.3":"Mengambil keputusan dan bertindak secara konsisten dalam mengembangkan potensi dan budaya belajar Murid","S.1":"Berkomunikasi secara inklusif, empatik, dan efektif secara lisan, tulisan, dan/atau isyarat dengan memperhatikan keragaman dan kebutuhan Murid","S.2":"Berkolaborasi dengan Murid, sesama Pendidik, Tenaga Kependidikan selain Pendidik, orang tua/wali Murid, dan masyarakat untuk meningkatkan kualitas pembelajaran","S.3":"Berpartisipasi aktif dalam organisasi profesi dan komunitas pembelajaran untuk pengembangan keprofesian berkelanjutan","PF.1":"Menguasai tujuan pendidikan terutama pada Satuan Pendidikan yang diampu","PF.2":"Menguasai disiplin ilmu sesuai dengan materi/muatan pembelajaran atau pembimbingan","PF.3":"Memahami potensi dan kebutuhan belajar Murid berdasarkan karakteristik materi pembelajaran atau pembimbingan dan konteks lokal","PF.4":"Memahami, menerapkan, dan mengembangkan kurikulum secara adaptif dan kontekstual sesuai perkembangan zaman","PF.5":"Mengembangkan praktik profesional pendidikan secara konseptual, empiris, kreatif, dan inovatif"},"packages":[{"id":1,"title":"Paket 1","version":"2026-11-18.6","file":"bank_soal_80.json","reviewFile":"references/Bank_Soal_80_dan_Pembahasan.md","questions":[{"id":1,"code":"P.1","type":"PG","stem":"Dalam rancangan ERD perpustakaan kelas, beberapa murid menjadikan nama siswa sebagai primary key karena setiap murid punya nama. Guru menemukan dua murid bernama Nisa. Tindakan pembelajaran yang paling tepat adalah ...","options":["Menjelaskan definisi PK, lalu meminta murid menerapkannya tanpa menguji dua nama yang sama.","Menguji dua rekaman bernama Nisa, lalu membimbing revisi ke ID unik yang tidak kosong.","Menambahkan indeks biasa pada nama_siswa agar pencarian cepat sekaligus dianggap menjamin keunikan.","Memakai gabungan nama dan kelas, lalu menyimpulkan keunikan tanpa menguji murid bernama sama di satu kelas."],"key":"B","why":"Pertentangan data nyata mengungkap miskonsepsi: nama tidak menjamin keunikan, sedangkan ID siswa dapat menjadi PK. Guru membantu murid menemukan alasan sebelum memperbaiki ERD.","section":"PCK","package":1,"uid":"p1-001","explanations":["Definisi tanpa uji nama kembar belum membongkar alasan murid memilih nama.","ID unik dan tidak kosong memenuhi identitas baris; uji dua Nisa membuat kebutuhan itu terlihat.","Indeks biasa mempercepat pencarian tetapi tidak mewajibkan keunikan.","Nama dan kelas juga dapat sama; gabungan atribut harus dibuktikan memenuhi keunikan."]},{"id":2,"code":"P.1","type":"MCMA","stem":"Kelompok merancang basis data peminjaman alat lab. Guru ingin menghubungkan konsep relasi satu-ke-banyak dengan implementasi SQL. Aktivitas mana yang paling mendukung? Pilih semua jawaban yang tepat.","options":["Mengabaikan tabel referensi agar latihan lebih singkat.","Menempatkan id_siswa pada tabel peminjaman dan menguji data yang terhubung.","Meminta murid menjelaskan dampak jika id_siswa pada peminjaman tidak merujuk siswa yang ada.","Meminta murid menyalin definisi foreign key berulang kali.","Membuat contoh satu siswa yang memiliki beberapa peminjaman."],"key":["B","C","E"],"why":"Contoh kardinalitas, implementasi FK, dan pengujian referensi menghubungkan model relasi dengan perilaku basis data.","section":"PCK","package":1,"uid":"p1-002","explanations":["Tanpa tabel yang dirujuk, integritas FK tidak dapat dipelajari dengan benar.","FK di sisi banyak menghubungkan setiap pinjaman dengan siswa yang sesuai.","Kasus ID tak dikenal menguji fungsi constraint untuk mencegah referensi yatim.","Menyalin definisi tidak menunjukkan hubungan antara satu siswa dan banyak pinjaman.","Contoh beberapa pinjaman satu siswa memperlihatkan kardinalitas 1:N."]},{"id":3,"code":"P.1","type":"PG","stem":"Setelah menambahkan atribut required pada formulir Laravel, murid menganggap validasi di server tidak diperlukan. Cara paling tepat meluruskan pemahaman itu adalah ...","options":["Mengandalkan required browser untuk semua request.","Menambahkan pemeriksaan JavaScript yang menampilkan pesan sebelum submit tanpa pemeriksaan di server.","Menguji permintaan langsung ke server yang tidak melalui validasi browser, lalu membimbing validasi required dan format email di server.","Memberi peringatan visual ketika email kosong sambil tetap menerima request yang dikirim ke server."],"key":"C","why":"Validasi browser membantu pengalaman pengguna, tetapi pemeriksaan data tetap diperlukan di server. Demonstrasi request memperlihatkan alasan teknisnya.","section":"PCK","package":1,"uid":"p1-003","explanations":["Validasi browser dapat dilewati sehingga tidak menjamin penerimaan di server.","JavaScript juga berjalan di klien dan tidak melindungi request yang dikirim langsung.","Request langsung menunjukkan batas validasi klien; pemeriksaan server menolak data kosong atau format salah.","Warna peringatan membantu antarmuka tetapi tidak menolak data tidak valid di server."]},{"id":4,"code":"P.1","type":"Kategori","stem":"Guru memakai dua tabel kecil, siswa dan peminjaman, untuk membangun pemahaman JOIN. Nilai tiap tindakan sebagai Tepat atau Tidak tepat.","options":["Murid menjelaskan mengapa baris tertentu muncul atau tidak muncul dalam hasil INNER JOIN.","Murid memprediksi hasil JOIN sebelum menjalankan query, lalu membandingkan prediksi dengan keluaran.","Guru langsung memberikan query jadi tanpa membahas relasi tabel."],"key":["T","T","F"],"why":"Prediksi, uji, dan penjelasan hasil membangun model mental. Query yang hanya disalin dapat menghasilkan keluaran tanpa pemahaman relasi.","section":"PCK","package":1,"uid":"p1-004","explanations":["Alasan kemunculan baris menunjukkan pemahaman pasangan yang cocok pada INNER JOIN.","Prediksi sebelum eksekusi mengungkap model mental murid tentang hasil JOIN.","Query jadi tanpa relasi dapat disalin tanpa memahami kondisi penggabungan."]},{"id":5,"code":"P.1","type":"PG","stem":"Saat mengenalkan objek dalam pemrograman berorientasi objek, murid menyamakan class dan object. Representasi awal mana yang paling membantu?","options":["Menelusuri dua instans dari satu class dan membandingkan perubahan atributnya.","Menghafalkan deklarasi class tanpa membuat instans.","Menggambarkan dua objek sebagai satu keadaan global yang selalu sama.","Mengenalkan hierarki pewarisan lebih dahulu sebelum menguji apakah murid membedakan rancangan dan instans."],"key":"A","why":"Contoh dua objek dari satu class membedakan cetak biru dan instans sambil mempertahankan keterkaitan konsep dengan kode.","section":"PCK","package":1,"uid":"p1-005","explanations":["Dua instans memperlihatkan rancangan bersama dan keadaan objek yang berbeda.","Hafalan deklarasi belum membedakan class dari hasil instansiasinya.","Keadaan global tunggal justru menyesatkan tentang keadaan tiap objek.","Pewarisan menambah konsep baru sebelum miskonsepsi dasar diselesaikan."]},{"id":6,"code":"P.6","type":"MCMA","stem":"Kelompok belajar kolaborasi Git pada proyek website kelas. Bukti pemahaman alur kerja yang layak diminta guru adalah ... Pilih semua yang tepat.","options":["Memperlihatkan commit dengan pesan yang menjelaskan perubahan.","Menjelaskan kapan sebuah branch perlu digabung dan bagaimana menangani konflik.","Memastikan semua murid memakai satu akun agar mudah.","Menjelaskan perubahan lewat perbandingan diff pada dua versi kode.","Mengumpulkan satu file ZIP terakhir tanpa riwayat perubahan."],"key":["A","B","D"],"why":"Commit, penjelasan merge, dan diff memberi bukti proses serta pemahaman kolaborasi Git. ZIP akhir hanya menunjukkan produk; akun bersama mengaburkan kontribusi individu.","section":"PCK","package":1,"uid":"p1-006","explanations":["Commit bermakna memperlihatkan unit perubahan dan alasan pengerjaannya.","Penjelasan merge dan konflik menunjukkan pemahaman penggabungan pekerjaan.","Akun bersama mengaburkan identitas kontribusi dan tanggung jawab.","Diff memperlihatkan perubahan konkret antarversi yang dapat dijelaskan murid.","ZIP akhir tidak menunjukkan urutan perubahan atau keputusan integrasi."]},{"id":7,"code":"P.1","type":"PG","stem":"Pada kasus transaksi koperasi sekolah, setiap transaksi bisa berisi banyak jenis barang. Murid membuat satu kolom barang1, barang2, barang3 pada tabel transaksi. Langkah pemantik pembelajaran yang paling tepat adalah ...","options":["Menambah kolom barang hingga jumlah terbesar saat ini.","Menyatukan daftar barang dan jumlah menjadi satu teks.","Menguji transaksi enam barang dengan jumlah berbeda, lalu membimbing rancangan tabel detail yang berelasi.","Membuat tabel transaksi terpisah untuk setiap barang."],"key":"C","why":"Kasus enam barang menonjolkan keterbatasan kolom berulang dan kebutuhan tabel detail yang terhubung dengan transaksi serta barang.","section":"PCK","package":1,"uid":"p1-007","explanations":["Penambahan kolom tetap membatasi jumlah barang dan mengulang struktur.","Teks gabungan menyulitkan pengujian jumlah, pencarian, dan relasi tiap barang.","Baris detail dapat menampung jumlah barang bervariasi dan kuantitas masing-masing.","Tabel per jenis barang memecah proses transaksi yang sama dan menyulitkan query lintas barang."]},{"id":8,"code":"P.1","type":"Kategori","stem":"Guru mengajar perulangan dengan tabel pelacakan nilai variabel. Nilai tindakan sebagai Tepat atau Tidak tepat.","options":["Memulai tabel pelacakan dari iterasi kedua dan mengabaikan nilai awal karena tidak memengaruhi penelusuran.","Membandingkan pelacakan manual dengan keluaran program lalu membahas selisihnya.","Menilai jawaban benar dari keluaran akhir saja tanpa memeriksa alasan murid."],"key":["F","T","F"],"why":"Trace table membantu menjelaskan keadaan program, bukan hanya hasil akhir. Membandingkan hasil merupakan kesempatan refleksi.","section":"PCK","package":1,"uid":"p1-008","explanations":["Nilai awal diperlukan untuk menelusuri program secara lengkap; mengabaikannya dapat menyebabkan langkah pertama dan hasil pelacakan keliru.","Selisih pelacakan dan eksekusi menjadi bukti untuk meninjau langkah yang salah.","Keluaran saja dapat kebetulan benar dan menyembunyikan penalaran yang keliru."]},{"id":9,"code":"P.2","type":"PG","stem":"Asesmen awal menunjukkan sebagian murid sudah lancar SELECT-WHERE, sebagian belum mengenal kondisi WHERE. Strategi paling responsif adalah ...","options":["Mengulang semua SELECT dengan kegiatan dan tempo identik agar semua murid memperoleh perlakuan yang sama.","Membedakan bantuan dan tantangan secara fleksibel, lalu mengecek tujuan inti yang sama.","Menetapkan kelompok mahir dan belum mampu untuk satu semester berdasarkan hasil asesmen awal tersebut.","Meminta murid mahir menyelesaikan query teman yang kesulitan agar keluaran setiap kelompok memenuhi target."],"key":"B","why":"Diferensiasi menyesuaikan jalan menuju tujuan yang sama berdasarkan kebutuhan nyata; bukan pelabelan kelompok tetap.","section":"PCK","package":1,"uid":"p1-009","explanations":["Pengulangan seragam mengabaikan kebutuhan dukungan dan pengayaan yang terungkap.","Dukungan fleksibel mengikuti bukti kesiapan dan dapat diubah setelah cek ulang.","Satu asesmen tidak membenarkan pelabelan kemampuan yang permanen.","Produk yang dikerjakan teman tidak membuktikan pemahaman murid yang dibantu."]},{"id":10,"code":"P.2","type":"Kategori","stem":"Guru ingin semua murid dapat menguji query SQL. Empat murid belum mendapat komputer. Nilai keputusan berikut sebagai Tepat atau Tidak tepat.","options":["Menetapkan nilai akhir keterampilan hanya dari murid yang mendapat komputer, tanpa memberi kesempatan asesmen setara kepada murid lain.","Menyiapkan tugas prediksi query atau rancangan ERD saat menunggu giliran praktik.","Menyusun giliran operator, penguji, dan pencatat sehingga semua berperan dan berganti peran."],"key":["F","T","T"],"why":"Rotasi dan tugas tanpa perangkat menjaga partisipasi serta kesempatan menunjukkan capaian. Penilaian harus adil terhadap akses.","section":"PCK","package":1,"uid":"p1-010","explanations":["Nilai akhir itu mengecualikan murid yang belum mendapat kesempatan menunjukkan keterampilan; ini berbeda dari asesmen bergiliran.","Prediksi query dan ERD menjaga aktivitas berpikir saat menunggu praktik.","Rotasi memastikan akses ke praktik dan tanggung jawab dibagi."]},{"id":11,"code":"P.2","type":"MCMA","stem":"Murid diminta menelusuri percabangan untuk masukan tertentu. Seorang murid kesulitan membaca tangkapan layar kode yang kecil karena hambatan penglihatan. Pilih semua penyesuaian yang tepat.","options":["Memperbesar judul slide sementara kode tetap disajikan sebagai tangkapan layar kecil.","Memastikan kontras dan keterbacaan bahan praktik.","Mengizinkan murid menjelaskan jalur percabangan secara lisan atau tertulis untuk masukan yang sama.","Mengecualikan murid dari asesmen agar tidak kesulitan.","Menyediakan teks kode yang dapat diperbesar atau dibaca pembaca layar."],"key":["B","C","E"],"why":"Penyesuaian akses dan cara respons dapat menjaga target kompetensi. Menghapus kesempatan praktik atau asesmen bukan pilihan inklusif.","section":"PCK","package":1,"uid":"p1-011","explanations":["Perubahan judul tidak mengatasi hambatan membaca kode yang diperlukan untuk menelusuri percabangan.","Kontras dan keterbacaan mengurangi hambatan visual pada bahan.","Cara menyampaikan jawaban dapat disesuaikan sambil tetap meminta penalaran jalur percabangan untuk masukan yang sama.","Pengecualian asesmen menghilangkan bukti capaian alih-alih memperbaiki aksesnya.","Kode berbentuk teks memungkinkan pembesaran dan teknologi bantu."]},{"id":12,"code":"P.2","type":"PG","stem":"Murid yang cepat selesai CRUD mulai tidak tertantang, sementara teman lain masih membuat tabel. Tindakan terbaik adalah ...","options":["Memberi tantangan uji batas bagi yang siap dan contoh bertahap bagi yang masih membuat tabel.","Meminta murid cepat menyelesaikan kode kelompok lain.","Menghentikan semua kegiatan sampai rancangan tabel tiap murid selesai, termasuk bagi murid yang siap melanjutkan.","Memberi tambahan salinan CRUD yang sama kepada murid cepat tanpa menentukan tujuan atau tantangan baru."],"key":"A","why":"Tantangan pengayaan dan scaffolding disesuaikan kesiapan. Tutor sebaya boleh membantu, tetapi tidak menggantikan tanggung jawab guru.","section":"PCK","package":1,"uid":"p1-012","explanations":["Pengayaan dan bantuan bertahap memberi tantangan sesuai kesiapan masing-masing.","Mengerjakan kode teman mengambil kesempatan belajar dan mengaburkan bukti individu.","Menunggu produk identik tidak memberi kegiatan yang sesuai kebutuhan berbeda.","Salinan tambahan menambah beban tanpa memperluas pemahaman."]},{"id":13,"code":"P.2","type":"PG","stem":"Dalam diskusi ERD ada murid yang sulit mengikuti penjelasan lisan di ruang bising. Respons guru yang paling tepat adalah ...","options":["Menegur kurang fokus sebelum memeriksa hambatan akses.","Memperkeras suara tanpa mengecek pemahaman.","Memberi instruksi tertulis dan ERD berlabel, lalu mengecek secara pribadi apakah murid dapat menjelaskan relasinya.","Membebaskan murid dari penjelasan hubungan entitas dan hanya meminta salinan gambar agar tugasnya lebih ringan."],"key":"C","why":"Akses multimodal dan pengecekan pemahaman membuat murid dapat ikut tanpa distigma.","section":"PCK","package":1,"uid":"p1-013","explanations":["Teguran sebelum memeriksa hambatan akses tidak mengatasi kesulitan mengikuti penjelasan di ruang bising.","Volume saja tidak menjamin instruksi terbaca atau dipahami.","Instruksi tertulis dan label membantu akses penjelasan; murid tetap diminta menjelaskan hubungan entitas.","Pembebasan tujuan menghilangkan kesempatan belajar padahal akses dapat diperbaiki."]},{"id":14,"code":"P.3","type":"PG","stem":"Saat latihan debugging banyak murid malu karena error. Guru ingin kelas aman untuk mencoba. Respons terbaik adalah ...","options":["Memperbaiki seluruh error tanpa penelusuran oleh murid.","Memodelkan diagnosis, menyepakati komentar yang aman, lalu memberi kesempatan mencoba dan merevisi.","Mengganti debugging dengan menyalin kode jadi.","Melombakan jumlah error sebelum mengajarkan diagnosis."],"key":"B","why":"Menormalisasi kesalahan sebagai bukti proses belajar dan mengajarkan strategi diagnosis mendukung keberanian bereksperimen.","section":"PCK","package":1,"uid":"p1-014","explanations":["Perbaikan oleh guru saja tidak membangun keberanian dan strategi diagnosis murid.","Pemodelan dan kesepakatan komentar aman membuat error dapat dipakai sebagai bukti belajar.","Menyalin kode menghilangkan kesempatan berlatih diagnosis.","Lomba tanpa dukungan dapat memperkuat ketakutan membuat kesalahan."]},{"id":15,"code":"P.3","type":"Kategori","stem":"Dalam proyek penjadwalan piket lab, murid dapat menyusun urutan tugas tetapi belum melihat manfaat algoritma bagi pengguna. Nilai rancangan pembelajaran sebagai Tepat atau Tidak tepat.","options":["Menilai kebermaknaan proyek dari banyaknya animasi presentasi tanpa menguji apakah jadwal dapat dilaksanakan.","Membuka dengan kendala jadwal yang benar-benar dihadapi kelas dan mengajak murid menetapkan tujuan solusi.","Mengajak murid merefleksikan bagaimana aturan penjadwalan membantu pembagian tugas yang adil."],"key":["F","T","T"],"why":"Masalah penjadwalan nyata, tujuan yang disadari, dan refleksi dampak menghubungkan algoritma dengan pengalaman kelas.","section":"PCK","package":1,"uid":"p1-015","explanations":["Animasi presentasi tidak membuktikan jadwal memenuhi kendala pengguna.","Kendala nyata dan tujuan bersama membantu murid menyadari manfaat algoritma.","Refleksi dampak pembagian tugas menghubungkan konsep dengan pengalaman kelas."]},{"id":16,"code":"P.3","type":"MCMA","stem":"Dua kelompok memakai cara pencarian berbeda yang sama-sama lolos uji. Sebagian murid enggan menjelaskan caranya karena takut diejek. Pilih praktik guru yang mendukung diskusi aman dan menantang.","options":["Menutup pembahasan alternatif setelah satu kode berhasil dijalankan.","Memberi kriteria keberhasilan yang jelas dan kesempatan memperbaiki produk.","Memuji proses pengujian dan argumentasi, bukan hanya jawaban tercepat.","Mewajibkan semua murid meniru satu cara tanpa berdiskusi.","Mengizinkan kelompok menjelaskan alternatif solusi tanpa diejek."],"key":["B","C","E"],"why":"Keamanan psikologis, kesempatan revisi, dan penghargaan atas alasan membangun keterlibatan tanpa menurunkan standar.","section":"PCK","package":1,"uid":"p1-016","explanations":["Keberhasilan satu kode tidak menghilangkan manfaat membandingkan alasan dan hasil pengujian solusi lain.","Kriteria dan kesempatan revisi menjaga tantangan sekaligus memberi arah perbaikan.","Pengujian dan argumentasi merupakan proses belajar yang layak dihargai.","Satu cara wajib tanpa diskusi menutup kesempatan menalar alternatif yang sah.","Alternatif dapat dibahas jika suasana melindungi murid dari ejekan."]},{"id":17,"code":"P.3","type":"PG","stem":"Menjelang akhir sesi array, beberapa murid mengatakan pencarian selalu berhenti di elemen pertama meski data belum ditemukan. Guru memiliki delapan menit untuk menjaga keterlibatan sekaligus menguji pemahaman. Kegiatan terbaik adalah ...","options":["Menayangkan video motivasi agar murid kembali bersemangat tanpa menghubungkannya dengan kondisi berhenti pencarian.","Meminta murid menyalin istilah array sampai bel selesai agar semua tetap terlihat bekerja.","Meminta murid tercepat menyebut hasil pencarian sementara murid lain menyalin hasil tanpa menelusuri langkahnya.","Menguji target yang tidak ada lewat kartu array, lalu meminta revisi pemahaman kondisi berhenti."],"key":"D","why":"Tantangan singkat yang relevan, terdukung, dan diakhiri refleksi menjaga keterlibatan sambil mengungkap miskonsepsi kondisi berhenti.","section":"PCK","package":1,"uid":"p1-017","explanations":["Motivasi umum tidak menguji miskonsepsi berhenti di elemen pertama.","Menyalin istilah tidak menguji langkah pencarian.","Jawaban satu murid tidak memberi bukti atau keterlibatan murid lain.","Target yang tidak ada mengharuskan menelusuri array dan merefleksikan kondisi berhenti."]},{"id":18,"code":"P.4","type":"PG","stem":"Murid menggunakan AI untuk membuat kode autentikasi dan menganggap hasilnya pasti aman. Guru sebaiknya ...","options":["Melarang pembahasan AI tanpa memeriksa kode murid.","Menguji kode bersama murid, memeriksa penyimpanan kata sandi dan validasi masukan, lalu membahas keterbatasan AI.","Memberi nilai penuh setelah kode berjalan dan menunda pemeriksaan keamanan karena autentikasi sudah tampak berhasil.","Mengunggah kredensial server sekolah ke layanan AI agar perbaikan dapat disesuaikan langsung dengan sistem sebenarnya."],"key":"B","why":"Literasi AI mencakup verifikasi fungsi, keamanan, sumber data, dan tanggung jawab penggunaan.","section":"PCK","package":1,"uid":"p1-018","explanations":["Larangan pembicaraan tidak mengajarkan verifikasi keluaran AI.","Uji dan penjelasan keamanan melatih penggunaan AI secara kritis.","Program berjalan belum membuktikan keamanan autentikasi.","Kredensial asli tidak diperlukan untuk belajar dan membukanya menambah risiko akses."]},{"id":19,"code":"P.4","type":"Kategori","stem":"Guru memakai platform daring agar murid membandingkan validasi formulir di browser dan server. Sebagian murid hanya dapat belajar luring. Nilai keputusan berikut sebagai Tepat atau Tidak tepat.","options":["Memilih platform dari banyaknya fitur dan mengubah tujuan agar seluruh fitur dipakai.","Mengunggah data identitas siswa asli ke layanan publik agar contoh terlihat realistis.","Menyediakan contoh formulir dan server lokal yang dapat diuji saat akses daring terbatas."],"key":["F","F","T"],"why":"Pemilihan platform harus mendukung pengujian validasi, menjaga privasi, dan menyediakan akses yang sesuai kondisi murid. Banyak fitur atau data identitas asli tidak menjamin tujuan itu tercapai.","section":"PCK","package":1,"uid":"p1-019","explanations":["Jumlah fitur tidak menunjukkan apakah platform membantu murid memahami perbedaan validasi browser dan server.","Identitas asli di layanan publik tidak diperlukan dan melanggar prinsip privasi.","Contoh lokal mempertahankan kesempatan membandingkan validasi browser dan server tanpa bergantung pada jaringan luar."]},{"id":20,"code":"P.4","type":"MCMA","stem":"Internet lab terputus. Guru ingin murid memahami alur request-response API, bukan sekadar menghafal istilah. Pilih semua adaptasi yang tepat.","options":["Memakai kartu berisi method, path, dan respons untuk menelusuri pertukaran pesan sebelum uji lokal.","Mengganti tujuan menjadi menghafal nama layanan API publik karena layanan tidak dapat diakses.","Memakai server simulasi lokal yang sudah disiapkan agar murid mengamati request dan respons tanpa internet.","Meminta prediksi respons untuk beberapa request lalu membandingkannya dengan simulasi lokal.","Menampilkan tangkapan layar respons saja dan menganggap murid sudah membuktikan hubungan request-response."],"key":["A","C","D"],"why":"Representasi pesan, simulasi lokal, dan prediksi-uji mempertahankan tujuan API ketika internet terputus; sekadar istilah atau gambar hasil tidak cukup.","section":"PCK","package":1,"uid":"p1-020","explanations":["Kartu pesan mengonkretkan alur sebelum murid menguji pertukaran data.","Nama layanan tidak menggantikan pemahaman alur pesan.","Server lokal memungkinkan pengamatan teknis tanpa koneksi luar.","Perbandingan prediksi dan respons lokal menguji model mental murid.","Gambar respons tanpa hubungan dengan request belum membuktikan pemahaman alur."]},{"id":21,"code":"P.4","type":"PG","stem":"Guru hendak memilih aplikasi gambar ERD daring. Murid mampu menggambar ERD di kertas. Prinsip pilihan paling tepat adalah ...","options":["Memilih alat populer sebagai bukti manfaat belajar.","Mewajibkan semua tahap digital meski waktu tersita.","Memakai alat bila membantu uji, revisi, atau kolaborasi; tetap memakai kertas bila tujuan tercapai.","Mengutamakan hasil digital dalam nilai meskipun ERD kertas memiliki hubungan dan alasan yang lebih tepat."],"key":"C","why":"Alat dipilih jika membantu murid menguji dan merevisi relasi pada ERD; kertas tetap dapat dipakai bila tujuan itu tercapai.","section":"PCK","package":1,"uid":"p1-021","explanations":["Popularitas tidak membuktikan manfaat atau akses yang sesuai kelas.","Registrasi yang menyita waktu tanpa manfaat dapat menghambat tujuan.","Pengujian relasi dan revisi adalah nilai tambah; media dipilih sesuai manfaatnya.","Format digital saja tidak membuktikan kualitas ERD lebih baik dari kertas."]},{"id":22,"code":"P.4","type":"PG","stem":"Sebuah generator kode AI menghasilkan query yang menampilkan informasi pribadi siswa tanpa pembatasan. Tugas belajar yang paling tepat adalah ...","options":["Membandingkan query dengan kebutuhan akses, membatasi data keluaran, dan menguji hasilnya.","Memercayai query karena dapat dijalankan.","Mempublikasikan hasil berisi data pribadi untuk dinilai.","Mengganti topik keamanan dengan hafalan sintaks."],"key":"A","why":"Kritik terhadap keluaran otomatis menuntut pemahaman kebutuhan, minimisasi data, dan pengujian hasil.","section":"PCK","package":1,"uid":"p1-022","explanations":["Membandingkan kebutuhan dan keluaran melatih minimisasi serta pemeriksaan akses data.","Query yang dapat dijalankan belum tentu sesuai kebutuhan atau aman.","Publikasi memperluas paparan data yang justru perlu dibatasi.","Menghapus topik membuat murid kehilangan kesempatan belajar mengatasi masalahnya."]},{"id":23,"code":"P.5","type":"PG","stem":"Guru ingin memberi tugas rancangan basis data yang dekat dengan kehidupan murid. Masalah peminjaman alat olahraga sekolah tersedia dan datanya bisa disimulasikan. Kegiatan terbaik adalah ...","options":["Memberikan skema industri lengkap sebelum murid mengamati proses setempat agar rancangan terlihat profesional.","Meminta salinan skema dari internet sebagai hasil akhir tanpa membandingkannya dengan kebutuhan peminjaman.","Menilai rancangan dari banyaknya tabel yang dibuat, dengan asumsi jumlah tabel menunjukkan kelengkapan kebutuhan.","Mengobservasi alur peminjaman, memodelkan relasi, lalu menguji dengan transaksi contoh."],"key":"D","why":"Kebutuhan lokal yang konkret dapat menghubungkan konsep ERD, relasi, dan validasi rancangan.","section":"PCK","package":1,"uid":"p1-023","explanations":["Skema industri tanpa hubungan dengan konteks dapat menambah beban sebelum konsep terbentuk.","Salinan skema tidak menunjukkan pemahaman kebutuhan pengguna.","Jumlah tabel bukan ukuran kecocokan rancangan.","Observasi dan transaksi uji menghubungkan kebutuhan lokal dengan keputusan model data."]},{"id":24,"code":"P.5","type":"Kategori","stem":"Guru memilih kasus koperasi setempat untuk pembelajaran entitas dan relasi di SMK. Pengalaman murid tentang koperasi beragam. Nilai keputusan berikut sebagai Tepat atau Tidak tepat.","options":["Menggunakan transaksi tiruan untuk mengenali entitas dan relasi sambil menjelaskan proses koperasi yang belum dikenal murid.","Memilih konteks hanya karena tren walaupun tidak mendukung kompetensi yang dinilai.","Meminta murid yang belum mengenal koperasi menunggu tanpa aktivitas sampai teman lain selesai."],"key":["T","F","F"],"why":"Konteks lokal membantu jika relevan dan membuka beragam pengalaman; guru tidak boleh berasumsi semua murid sama.","section":"PCK","package":1,"uid":"p1-024","explanations":["Transaksi setempat menjadi sumber belajar pemodelan data; penjelasan proses membantu murid dengan pengalaman awal berbeda.","Tren tanpa hubungan dengan kompetensi tidak memberi alasan pedagogis pemilihan kasus.","Perbedaan pengalaman perlu dukungan atau konteks setara, bukan penghentian kesempatan belajar."]},{"id":25,"code":"P.5","type":"MCMA","stem":"Guru memilih kasus antrean layanan perpustakaan sekolah untuk mengajarkan algoritma FIFO. Komputer dipakai bergiliran. Pilih tindakan yang menjaga tujuan algoritma dan memanfaatkan sumber lokal.","options":["Murid bergiliran menjadi pemohon, petugas antrean, dan penelusur perubahan queue dengan kartu sebelum menguji kode.","Menilai pemahaman FIFO terutama dari kecepatan mengetik program yang dicontohkan guru.","Memakai catatan kedatangan tiruan untuk memeriksa urutan masuk dan keluar antrean.","Murid menjelaskan hasil simulasi kartu, lalu membandingkan urutannya dengan program saat mendapat perangkat.","Menyamakan FIFO dengan selalu melayani permintaan yang paling singkat tanpa membahas urutan kedatangan."],"key":["A","C","D"],"why":"Simulasi antrean lokal, data kedatangan, dan pembandingan dengan program menjaga konsep FIFO meskipun perangkat terbatas.","section":"PCK","package":1,"uid":"p1-025","explanations":["Peran kartu dan penelusuran queue memberi pengalaman konsep meskipun belum memakai komputer.","Kecepatan mengetik tidak menunjukkan urutan pengeluaran data.","Catatan kedatangan memungkinkan murid menguji aturan masuk lebih dahulu keluar lebih dahulu.","Pembandingan kartu dan program menghubungkan representasi lokal dengan implementasi.","Permintaan tersingkat adalah aturan lain; bukan definisi FIFO."]},{"id":26,"code":"P.5","type":"PG","stem":"Guru ingin murid memodelkan data produk dan transaksi dari usaha keluarga yang mereka kenal. Kelompok hendak memakai data pelanggan asli. Respons paling tepat adalah ...","options":["Menghapus nama tetapi tetap membagikan nomor telepon.","Membuat dataset sintetis yang mempertahankan kebutuhan usaha lokal serta membahas perlindungan data.","Menaruh data asli di akun bersama agar seluruh kelompok dan guru dapat memeriksa hasil praktik dengan mudah.","Meminta murid menyalin tabel contoh umum sebagai rancangan akhir untuk usaha tersebut."],"key":"B","why":"Kasus lokal tetap dapat dipakai tanpa membuka data pribadi; tujuan pembelajaran terletak pada model dan logika data.","section":"PCK","package":1,"uid":"p1-026","explanations":["Nomor telepon tetap dapat mengidentifikasi pelanggan; menghapus nama saja belum menghilangkan paparan.","Dataset sintetis mempertahankan proses usaha sebagai sumber belajar tanpa mengekspos pelanggan.","Akun bersama memperluas akses ke data yang tidak diperlukan untuk tujuan model basis data.","Tabel contoh dapat menjadi bantuan awal, tetapi salinannya belum membuktikan rancangan sesuai kebutuhan usaha yang sedang dipelajari."]},{"id":27,"code":"P.6","type":"PG","stem":"Sebelum mengajar PK dan FK, guru bertanya apakah dua orang boleh memiliki nama sama dan apakah dua peminjaman bisa dilakukan satu siswa. Fungsi utama pertanyaan itu ialah ...","options":["Memetakan gagasan awal tentang identitas unik dan relasi untuk memilih dukungan belajar.","Menetapkan nilai akhir dari dua jawaban awal.","Menguji hafalan sintaks JOIN lanjutan.","Menyaring murid yang boleh memakai komputer berdasarkan benar-salahnya dua jawaban awal tersebut."],"key":"A","why":"Pertanyaan sebelum pembelajaran memunculkan konsepsi awal dan membantu memilih dukungan belajar.","section":"PCK","package":1,"uid":"p1-027","explanations":["Pertanyaan memunculkan gagasan awal identitas unik dan relasi untuk merencanakan dukungan.","Sebelum pembelajaran, jawaban awal tidak cukup menjadi penilaian akhir capaian.","Pertanyaan tidak meminta sintaks SQL lanjutan.","Diagnosis bertujuan memberi dukungan, bukan melarang murid praktik."]},{"id":28,"code":"P.6","type":"MCMA","stem":"Murid menghasilkan query JOIN tetapi sebagian rekaman hilang. Bukti asesmen formatif apa yang membantu guru menemukan sumber masalah? Pilih semua.","options":["Memeriksa apakah kondisi JOIN dan data kunci cocok.","Memberikan nilai nol sebelum mengetahui alasan kesalahan.","Meminta murid menjelaskan tabel mana yang menjadi asal setiap kolom.","Mencatat hanya waktu tercepat menjalankan query.","Meminta prediksi baris yang seharusnya muncul dan membandingkannya dengan hasil."],"key":["A","C","E"],"why":"Penelusuran asal kolom, prediksi data, dan pemeriksaan kondisi JOIN menunjukkan miskonsepsi secara spesifik.","section":"PCK","package":1,"uid":"p1-028","explanations":["Kondisi dan nilai kunci membantu membedakan kesalahan query dari data tanpa pasangan.","Nilai nol tanpa diagnosis tidak memberi informasi sumber masalah.","Asal kolom membantu menemukan kekeliruan memahami relasi dan alias.","Kecepatan tidak menerangkan mengapa rekaman hilang.","Prediksi baris mengungkap hasil yang dipahami murid dan letak selisihnya."]},{"id":29,"code":"P.6","type":"Kategori","stem":"Guru membuat rubrik tugas ERD. Nilai pernyataan berikut sebagai Tepat atau Tidak tepat.","options":["Guru menjelaskan rubrik sebelum bekerja sehingga murid dapat menggunakannya untuk revisi.","Kriteria mencakup kecocokan entitas, PK, kardinalitas, dan alasan hubungan dengan kasus.","Penilaian hanya berdasarkan warna dan kerapian gambar, tanpa memeriksa kebenaran model."],"key":["T","T","F"],"why":"Rubrik selaras dengan tujuan belajar dan transparan sejak awal. Tampilan boleh dipertimbangkan, tetapi bukan inti kompetensi ERD.","section":"PCK","package":1,"uid":"p1-029","explanations":["Rubrik di awal memberi standar yang dapat dipakai murid meninjau rancangan.","Entitas, PK, kardinalitas, dan alasan mengukur substansi ERD.","Warna dapat membantu komunikasi tetapi tidak menggantikan ketepatan model."]},{"id":30,"code":"P.6","type":"PG","stem":"Murid menggambar relasi siswa–peminjaman sebagai 1:1 padahal satu siswa dapat meminjam berkali-kali. Umpan balik yang paling berguna adalah ...","options":["Mengganti simbol 1:1 menjadi 1:N tanpa meminta alasan.","Merapikan gambar sambil menganggap relasinya benar.","Meminta uji satu siswa dengan tiga transaksi, lalu membimbing penjelasan revisi kardinalitas.","Menyalin gambar kunci tanpa menjelaskan kardinalitas."],"key":"C","why":"Umpan balik spesifik memicu pengujian model terhadap kasus sehingga siswa memahami alasan perbaikan.","section":"PCK","package":1,"uid":"p1-030","explanations":["Perubahan simbol tanpa alasan tidak membantu murid menguji modelnya.","Kerapian tidak menyelesaikan ketidaksesuaian kardinalitas dengan transaksi.","Kasus tiga transaksi memberi bukti langsung untuk memperbaiki kardinalitas.","Menyalin gambar kunci tidak menjelaskan hubungan model dengan kebutuhan."]},{"id":31,"code":"P.6","type":"PG","stem":"Setelah kuis JOIN, 70% murid salah membedakan INNER dan LEFT JOIN. Langkah selanjutnya paling tepat adalah ...","options":["Memberikan contoh INNER JOIN dan LEFT JOIN yang seluruh barisnya memiliki pasangan.","Menganalisis kesalahan, mengajar ulang memakai baris tanpa pasangan, lalu mengecek penalaran.","Mengulang kuis sampai nilai naik tanpa membahas alasan salah, dengan asumsi pengulangan otomatis membentuk konsep.","Mengajarkan rumus LEFT JOIN selalu sama banyak dengan tabel kiri tanpa memeriksa kemungkinan beberapa pasangan."],"key":"B","why":"Hasil asesmen harus dipakai untuk mengubah pengajaran. Data tanpa pasangan memberi bukti konkret perbedaan jenis JOIN.","section":"PCK","package":1,"uid":"p1-031","explanations":["Data dengan semua baris berpasangan belum memperlihatkan perbedaan yang menjadi kesulitan kelas; B menargetkan baris tanpa pasangan dan mengecek ulang penalaran.","Baris tanpa pasangan memperlihatkan perbedaan INNER dan LEFT JOIN secara konkret.","Kuis berulang tanpa umpan balik tidak menargetkan penyebab salah.","LEFT JOIN dapat menghasilkan lebih banyak baris kiri jika ada banyak pasangan; rumus itu keliru."]},{"id":32,"code":"P.6","type":"MCMA","stem":"Tujuan praktik ialah merancang uji fungsi hitungDiskon(total) dengan batas diskon pada total >= 100000. Bukti asesmen apa yang relevan untuk mengetahui penalaran murid? Pilih semua.","options":["Catatan perbandingan hasil aktual dan hasil yang diharapkan untuk menemukan kegagalan.","Penjelasan alasan memilih kasus batas dan dampaknya jika operator >= diganti >.","Jumlah baris kode uji tanpa memeriksa perilaku apa yang diuji.","Daftar input di bawah, tepat pada, dan di atas batas beserta hasil yang diharapkan.","Tangkapan layar editor tanpa input dan hasil eksekusi."],"key":["A","B","D"],"why":"Input batas, perbandingan expected-actual, dan alasan pemilihan kasus menunjukkan penalaran pengujian; penampilan atau jumlah kode tidak cukup.","section":"PCK","package":1,"uid":"p1-032","explanations":["Expected-actual memperlihatkan perilaku yang menyimpang dari aturan.","Perubahan operator tepat di batas menunjukkan alasan pemilihan kasus.","Jumlah kode tidak menjamin kasus penting atau hasilnya diperiksa.","Input sekitar batas memperlihatkan transisi aturan diskon.","Editor tanpa eksekusi tidak menunjukkan fungsi diuji."]},{"id":33,"code":"P.6","type":"PG","stem":"Tujuan belajar ialah murid mampu memecah program kasir menjadi fungsi dengan tanggung jawab jelas dan menjelaskan aliran datanya. Asesmen paling selaras adalah ...","options":["Meminta murid menandai deklarasi dan pemanggilan fungsi pada program yang sudah dipecah.","Memberi skor semakin tinggi untuk semakin banyak fungsi tanpa memeriksa tanggung jawab serta aliran datanya.","Meminta murid menyalin hasil refaktor guru tanpa menjelaskan pemilihan parameter dan hasil setiap fungsi.","Meminta refaktor, penjelasan masukan-keluaran tiap fungsi, dan uji kesetaraan perilaku program."],"key":"D","why":"Refaktor beralasan disertai pengujian mengukur pembagian tanggung jawab dan aliran data, bukan jumlah fungsi atau hafalan definisi.","section":"PCK","package":1,"uid":"p1-033","explanations":["Menandai fungsi mengukur pengenalan struktur, belum kemampuan membagi tanggung jawab dan menjelaskan aliran data.","Banyak fungsi belum menjamin tanggung jawab jelas atau data mengalir benar.","Menyalin hasil refaktor tidak mengungkap alasan pemisahan.","Refaktor, penjelasan masukan-keluaran tiap fungsi, dan pengujian perilaku mengukur pembagian tanggung jawab serta aliran data secara langsung."]},{"id":34,"code":"P.6","type":"Kategori","stem":"Query murid untuk menampilkan semua siswa tidak memunculkan siswa tanpa peminjaman. Guru ingin murid memahami penyebabnya dan merevisi query. Nilai umpan balik berikut sebagai Tepat atau Tidak tepat.","options":["Memberi query benar untuk disalin sebagai perbaikan akhir.","Guru meminta murid memperbaiki hasilnya lalu menjelaskan perubahan dan alasan revisi.","Menunjukkan bagian query yang sudah benar, lalu meminta murid memeriksa hasil untuk siswa tanpa pasangan peminjaman."],"key":["F","T","T"],"why":"Umpan balik harus spesifik, aman, dan dapat ditindaklanjuti; revisi menunjukkan belajar dari asesmen.","section":"PCK","package":1,"uid":"p1-034","explanations":["Salinan query dapat memperbaiki keluaran, tetapi belum menunjukkan murid memahami penyebab hilangnya baris.","Penjelasan revisi membantu memastikan murid memahami perubahannya.","Petunjuk ini menghubungkan hasil yang hilang dengan perilaku penggabungan tabel tanpa langsung memberikan seluruh solusi."]},{"id":35,"code":"PF.1","type":"PG","stem":"Pembelajaran proyek aplikasi sekolah dianggap selesai jika website bisa dibuka. Agar tujuan pendidikan kejuruan tercapai lebih utuh, guru seharusnya juga ...","options":["Menilai alasan desain, tanggung jawab kerja, keamanan, dan tanggapan pengguna.","Menilai kesiapan kerja terutama dari kerapian halaman.","Menilai dari kemiripan tampilan dengan contoh.","Mengurutkan kemampuan kerja dari kecepatan mengetik tanpa meninjau kualitas solusi atau kontribusi kelompok."],"key":"A","why":"Kompetensi SMK mengaitkan penguasaan teknis, penalaran, kerja sama, etika, dan kemampuan beradaptasi.","section":"PCK","package":1,"uid":"p1-035","explanations":["Keputusan teknis, tanggung jawab, dan evaluasi pengguna menilai kecakapan kejuruan secara utuh.","Kerapian halaman belum cukup membuktikan fungsi, penalaran teknis, dan tanggung jawab kerja yang menjadi tujuan kejuruan.","Peniruan tampilan tidak menunjukkan kemampuan memenuhi kebutuhan.","Kecepatan mengetik bukan pengganti kualitas solusi dan etika kerja."]},{"id":36,"code":"PF.1","type":"Kategori","stem":"Proyek pembuatan sistem kelas dilakukan dalam pembelajaran. Nilai pernyataan sebagai Tepat atau Tidak tepat.","options":["Mengajarkan bahwa semua akun pengguna perlu hak admin agar akses lebih mudah.","Menganggap keberhasilan teknis membenarkan pengumpulan data pribadi berlebihan.","Mengaitkan kemampuan pemrograman dengan penyelesaian masalah nyata dan tanggung jawab sosial."],"key":["F","F","T"],"why":"Tujuan pendidikan menuntut kompetensi dan karakter; etika digital tidak boleh dikorbankan demi fitur.","section":"PCK","package":1,"uid":"p1-036","explanations":["Hak admin untuk semua akun tidak sesuai kebutuhan dan mengabaikan tanggung jawab pengelolaan akses.","Keberhasilan fitur tidak membenarkan pengumpulan data berlebihan.","Penyelesaian masalah dan tanggung jawab sosial mengaitkan teknik dengan tujuan pendidikan."]},{"id":37,"code":"PF.2","type":"PG","stem":"Saat mengajar keamanan aplikasi, murid membangun query dengan menggabungkan input pengguna ke string SQL. Penjelasan dan perbaikan yang tepat adalah ...","options":["Mengajarkan binding nilai dan membandingkan bagaimana data dipisahkan dari struktur SQL.","Menghapus petik lalu menganggap input lain pasti aman.","Memercayai validasi JavaScript untuk semua request.","Menyembunyikan error tanpa memperbaiki query."],"key":"A","why":"Parameter binding memisahkan data input dari struktur perintah SQL, sehingga efektif menjadi contoh konsep keamanan aplikasi.","section":"PCK","package":1,"uid":"p1-037","explanations":["Binding nilai memisahkan data dari struktur perintah; nama tabel dinamis tetap perlu mekanisme aman lain.","Menghapus petik bukan pengganti pemisahan data dan perintah.","Validasi klien dapat dilewati oleh request langsung.","Menyembunyikan error tidak memperbaiki kerentanan penggabungan input."]},{"id":38,"code":"PF.2","type":"MCMA","stem":"Dalam aplikasi koperasi, proses checkout menulis header transaksi dan detail barang. Simulasi kegagalan membuat header tersimpan tetapi detail tidak lengkap. Guru meminta murid menilai solusi yang menjaga atomisitas. Pilih semua yang tepat.","options":["Menangkap exception lalu tetap mengirim pesan sukses tanpa memeriksa konsistensi.","Menyimpulkan constraint foreign key saja menjamin semua langkah checkout selalu selesai bersama.","Membungkus penulisan terkait dalam satu transaksi basis data yang mendukung transaksi.","Melakukan commit header lebih dahulu agar selalu ada bukti meski penulisan detail gagal.","Melakukan rollback seluruh penulisan terkait jika satu langkah gagal dan menguji skenario kegagalannya."],"key":["C","E"],"why":"Atomisitas berarti seluruh perubahan terkait berhasil bersama atau dibatalkan bersama. Constraint relasi tidak menggantikan transaksi multi-langkah.","section":"PCK","package":1,"uid":"p1-038","explanations":["Pesan sukses setelah kegagalan menyembunyikan ketidakkonsistenan.","FK menjaga referensi, bukan menjamin beberapa operasi berhasil sebagai satu kesatuan.","Satu transaksi memungkinkan semua perubahan terkait di-commit bersama.","Commit header lebih awal menyisakan data parsial bila detail gagal.","Rollback dan simulasi gagal menunjukkan seluruh perubahan terkait dapat dibatalkan."]},{"id":39,"code":"PF.2","type":"PG","stem":"Murid mengirim form Laravel dengan method POST, tetapi route hanya didaftarkan untuk GET. Strategi pembelajaran tepat adalah ...","options":["Menambah token CSRF pada form saja dan menganggap permintaan POST kini pasti cocok dengan route GET.","Mengubah semua form penyimpanan menjadi GET agar sesuai route lama tanpa membahas maksud HTTP method.","Menelusuri method form dan route, lalu membetulkan route POST untuk operasi penyimpanan.","Menghapus validasi isian di controller dengan asumsi kegagalan mencapai route disebabkan aturan validasi data."],"key":"C","why":"Kesalahan method menjadi kesempatan memeriksa hubungan form, HTTP method, route, dan controller.","section":"PCK","package":1,"uid":"p1-039","explanations":["CSRF dan HTTP method menangani persoalan berbeda; token tidak membuat route GET menerima POST.","Mengubah penyimpanan ke GET menghindari diagnosis dan tidak sesuai maksud operasi.","Penelusuran request mengungkap ketidakcocokan dan mempertahankan method sesuai operasi.","Validasi isian tidak menyebabkan ketidakcocokan method route."]},{"id":40,"code":"PF.2","type":"Kategori","stem":"Tabel siswa berisi S1 dan S2; tabel peminjaman hanya berisi pinjaman milik S1. Query memakai ON siswa.id = peminjaman.id_siswa tanpa filter WHERE tambahan. Nilai konsep berikut sebagai Tepat atau Tidak tepat.","options":["Setiap LEFT JOIN selalu memiliki jumlah baris tepat sama dengan tabel kiri meski ada beberapa pasangan.","INNER JOIN pada kunci siswa hanya mengembalikan pasangan yang cocok dalam contoh ini.","LEFT JOIN dari tabel siswa ke peminjaman dapat tetap memunculkan S2 dengan kolom peminjaman bernilai NULL."],"key":["F","T","T"],"why":"INNER JOIN memerlukan pasangan; LEFT JOIN mempertahankan baris kiri, tetapi bisa menghasilkan lebih banyak baris jika satu baris kiri memiliki banyak pasangan.","section":"PCK","package":1,"uid":"p1-040","explanations":["Beberapa pinjaman S1 dapat menggandakan baris hasil sehingga jumlahnya tidak selalu sama dengan tabel kiri.","Tanpa filter tambahan, INNER JOIN mengembalikan baris yang cocok pada kondisi ON.","LEFT JOIN tetap memunculkan S2 tanpa pasangan dengan nilai kanan NULL."]},{"id":41,"code":"PF.2","type":"PG","stem":"Murid membuat kondisi “nilai >= 75” untuk menentukan tuntas. Saat nilai tepat 75, program menyatakan tuntas. Untuk menguji pemahaman kondisi batas, guru sebaiknya meminta ...","options":["Mengulang input 80 dan 90 untuk menguji batas 75.","Menguji 74, 75, dan 76 serta meminta alasan hasil operator >= pada tiap input.","Menguji 75 saja tanpa melihat kedua sisinya, lalu menyatakan seluruh perilaku perbandingan telah teruji.","Mengganti >= dengan > karena keduanya menghasilkan tuntas untuk contoh 80 yang sudah pernah dijalankan."],"key":"B","why":"Kasus batas 74, 75, 76 secara langsung menampakkan efek operator perbandingan.","section":"PCK","package":1,"uid":"p1-041","explanations":["Input jauh dari batas tidak membedakan >= dan > pada nilai 75.","Tiga input menguji kedua sisi dan titik batas sehingga makna operator terlihat.","Titik batas saja belum memeriksa perilaku sebelum dan sesudahnya.","Operator > tidak memasukkan 75 sehingga tidak setara dengan >=."]},{"id":42,"code":"PF.2","type":"MCMA","stem":"Murid membuat fungsi pencarian indeks dalam array. Tujuannya menguji bahwa hasil sesuai spesifikasi: kembalikan indeks pertama jika ada dan -1 jika tidak ada. Pilih semua rancangan uji yang benar.","options":["Menguji array kosong dan target yang tidak ada pada array berisi, dengan hasil yang diharapkan -1.","Menganggap hasil -1 salah untuk semua input karena indeks harus selalu nonnegatif.","Mengubah hasil yang diharapkan agar selalu mengikuti keluaran program tanpa meninjau spesifikasi.","Menguji array dengan target di dua posisi dan memastikan indeks kemunculan pertama yang dikembalikan.","Menyatakan satu contoh target di posisi awal sudah membuktikan seluruh kemungkinan benar."],"key":["A","D"],"why":"Spesifikasi menentukan hasil acuan pengujian: kemunculan pertama dan kondisi tidak ditemukan, termasuk array kosong, perlu dibedakan. Keluaran program bukan penentu hasil yang seharusnya benar.","section":"PCK","package":1,"uid":"p1-042","explanations":["Kedua input harus menghasilkan -1 sesuai kontrak tidak ditemukan.","Nilai -1 sengaja menjadi penanda tidak ditemukan dan bukan indeks elemen.","Hasil yang diharapkan harus berasal dari spesifikasi agar tes dapat mendeteksi kesalahan program.","Target berulang menguji syarat indeks pertama dalam spesifikasi.","Satu contoh awal tidak mencakup data berulang, kosong, atau target tidak ada."]},{"id":43,"code":"PF.3","type":"PG","stem":"Sebagian siswa memahami logika program tetapi kesulitan membaca instruksi teks panjang. Guru ingin mengukur logika seleksi kondisi. Penyesuaian terbaik adalah ...","options":["Memberi instruksi ringkas dan contoh masukan-keluaran, lalu meminta murid menyusun logika untuk kasus baru.","Mengganti asesmen logika dengan hafalan istilah.","Menurunkan target karena kesulitan membaca.","Menetapkan kerapian tulisan jawaban sebagai ukuran utama meskipun sasaran yang diminta ialah logika seleksi."],"key":"A","why":"Dukungan mengurangi hambatan bahasa sambil mempertahankan tuntutan menyusun logika seleksi. Hafalan istilah, penurunan target, dan penilaian tulisan tangan tidak mengukur tujuan yang sama.","section":"PCK","package":1,"uid":"p1-043","explanations":["Instruksi ringkas mengurangi hambatan membaca; murid tetap harus menyusun logika, bukan menyalin diagram solusi yang sudah lengkap.","Hafalan istilah mengganti kompetensi seleksi kondisi.","Hambatan bahasa tidak membuktikan ketidakmampuan logika.","Tulisan tangan bukan sasaran pemrograman yang diukur."]},{"id":44,"code":"PF.3","type":"MCMA","stem":"Sebelum proyek antarmuka aplikasi inventaris lokal, guru menemukan murid terbiasa layar besar tetapi calon pengguna memakai ponsel kecil dan jaringan lambat. Tujuan inti tetap kemampuan merancang dan menguji antarmuka yang dapat digunakan. Pilih adaptasi yang tepat.","options":["Menghilangkan tujuan pengujian antarmuka karena perangkat pengguna berbeda dari komputer lab.","Menyediakan prototipe lokal dan simulasi layar kecil untuk menguji akses ke fungsi inti.","Menganggap kebiasaan murid memakai media sosial otomatis membuktikan pemahaman desain antarmuka.","Membantu murid mengidentifikasi kebutuhan pengguna dan prasyarat tata letak sebelum membuat antarmuka.","Meminta murid membandingkan tugas pengguna pada dua ukuran layar dan menjelaskan hambatan yang ditemukan."],"key":["B","D","E"],"why":"Kebutuhan pengguna lokal dan karakteristik materi antarmuka menuntut pengujian ukuran layar serta dukungan prasyarat; kebiasaan memakai aplikasi belum membuktikan kemampuan merancang.","section":"PCK","package":1,"uid":"p1-044","explanations":["Perbedaan perangkat perlu diadaptasi, bukan menghapus kemampuan pengujian.","Prototipe lokal dan layar kecil menanggapi karakteristik penggunaan yang nyata.","Pemakai aplikasi belum tentu memahami prinsip perancangan antarmuka.","Identifikasi kebutuhan dan prasyarat membantu murid memasuki materi yang sesuai.","Perbandingan tugas pengguna menghasilkan bukti hambatan antarmuka."]},{"id":45,"code":"PF.3","type":"Kategori","stem":"Untuk menetapkan kesiapan kelas sebelum materi API, nilai tindakan berikut sebagai Tepat atau Tidak tepat.","options":["Memeriksa apakah murid sudah memahami request, response, dan format data sederhana.","Langsung memberi proyek integrasi API besar sebelum memeriksa pemahaman request dan format data.","Menganggap semua murid otomatis memahami API karena sering memakai aplikasi."],"key":["T","F","F"],"why":"Membaca kebutuhan berdasarkan prasyarat nyata, bukan asumsi kebiasaan memakai teknologi.","section":"PCK","package":1,"uid":"p1-045","explanations":["Prasyarat request-response memberi dasar menilai kesiapan API.","Proyek besar tanpa pemeriksaan prasyarat tidak menanggapi kebutuhan kesiapan murid.","Sering memakai aplikasi tidak menjamin memahami pertukaran data."]},{"id":46,"code":"PF.4","type":"PG","stem":"Sekolah perlu mengontekstualkan pembelajaran RPL dengan kebutuhan inventaris. Guru sedang menyusun alur tujuan pembelajaran. Pilihan terbaik adalah ...","options":["Mengganti capaian dengan dekorasi yang disukai.","Menulis tujuan mengikuti aktivitas yang populer.","Menurunkan tujuan analisis, model data, dan pengujian dari capaian dengan konteks inventaris.","Menetapkan dukungan sama tanpa memeriksa prasyarat."],"key":"C","why":"Adaptasi kurikulum tetap menurunkan tujuan dari capaian dan memilih konteks untuk mencapainya.","section":"PCK","package":1,"uid":"p1-046","explanations":["Dekorasi saja mengganti kompetensi yang seharusnya diturunkan dari capaian.","Aktivitas populer tanpa tujuan tidak membentuk alur kompetensi.","Tujuan teknis menjadi dasar; inventaris merupakan konteks penerapannya.","Menyamakan murid tanpa bukti awal mengabaikan kebutuhan pengembangan alur."]},{"id":47,"code":"PF.4","type":"MCMA","stem":"Framework web berubah versi. Guru ingin materi tetap relevan secara kurikuler. Mana yang tepat? Pilih semua.","options":["Memperbarui contoh sesuai dokumentasi tepercaya sambil menguji kompatibilitas.","Membandingkan perubahan sintaks dengan prinsip yang tetap berlaku.","Menghapus semua pelajaran dasar karena framework akan selalu berubah.","Mempertahankan prinsip request-response, validasi, dan pengelolaan data sebagai konsep lintas-versi.","Mewajibkan murid menghafal seluruh sintaks versi lama tanpa memahami konsep."],"key":["A","B","D"],"why":"Kurikulum adaptif memperbarui contoh tanpa mengorbankan konsep fundamental serta tujuan kompetensi.","section":"PCK","package":1,"uid":"p1-047","explanations":["Dokumentasi dan uji kompatibilitas menjaga ketepatan contoh baru.","Perbandingan perubahan membantu murid mengaitkan sintaks dengan prinsip.","Perubahan framework tidak menghapus relevansi dasar request dan data.","Konsep lintas-versi menjaga tujuan ketika sintaks alat berubah.","Hafalan versi lama tanpa konsep tidak mempersiapkan adaptasi."]},{"id":48,"code":"PF.4","type":"Kategori","stem":"Guru menyelaraskan unit analisis kebutuhan perangkat lunak dengan tujuan murid dapat menurunkan kriteria penerimaan dari kebutuhan pengguna. Nilai keputusan kurikuler sebagai Tepat atau Tidak tepat.","options":["Menyediakan kasus kebutuhan lokal dan meminta murid menjelaskan hubungan kebutuhan dengan kriteria penerimaan yang dapat diuji.","Menjadikan hafalan nama alat manajemen proyek sebagai satu-satunya asesmen kriteria penerimaan.","Menyusun rubrik yang memeriksa keterlacakan kebutuhan, kejelasan kriteria, dan kelayakan pengujiannya."],"key":["T","F","T"],"why":"Kriteria penerimaan diturunkan dari kebutuhan pengguna dan harus dapat diuji; tujuan, kegiatan, dan rubrik perlu mengukur kemampuan yang sama.","section":"PCK","package":1,"uid":"p1-048","explanations":["Kriteria yang diturunkan dari kebutuhan memungkinkan pembuktian ketercapaian tujuan.","Nama alat tidak menunjukkan kemampuan menyusun kriteria penerimaan.","Rubrik keterlacakan dan keterujian selaras dengan kompetensi analisis kebutuhan."]},{"id":49,"code":"PF.5","type":"PG","stem":"Guru mencatat bahwa murid berulang kali salah menentukan foreign key walau sudah diberi penjelasan. Tindakan pengembangan praktik paling ilmiah adalah ...","options":["Mengulang penjelasan sama dan menafsirkan kesalahan sebagai kurang usaha sebelum meninjau bukti kerja murid.","Menguji intervensi data berelasi dan menelaah bukti sebelum-sesudah beserta keterbatasannya.","Mengadopsi strategi populer tanpa menentukan pola kesalahan atau bukti perubahan yang hendak diamati.","Memakai soal akhir yang sudah dihafal sebagai satu-satunya bukti bahwa intervensi menghasilkan pemahaman FK."],"key":"B","why":"Perbaikan profesional bertumpu pada identifikasi masalah, tindakan beralasan, bukti hasil, dan refleksi.","section":"PCK","package":1,"uid":"p1-049","explanations":["Menyimpulkan kurang usaha tanpa bukti menghambat evaluasi pendekatan guru.","Intervensi beralasan dan bukti sebelum-sesudah mendukung perbaikan tanpa klaim sebab-akibat yang berlebihan.","Popularitas tidak memberi bukti efektivitas pada kelas ini.","Hafalan contoh dapat menaikkan nilai tanpa transfer pemahaman FK."]},{"id":50,"code":"PF.5","type":"MCMA","stem":"Setelah proyek web, guru menemukan murid belum menguji formulir dengan masukan kosong. Guru meminta masukan komunitas RPL untuk memperbaiki pembelajaran pengujian. Pilih tindakan yang etis dan bermanfaat.","options":["Membagikan rubrik pengujian formulir dan hasil belajar anonim untuk mendapat masukan.","Menyebarkan nilai beserta nomor telepon siswa kepada publik.","Menguji saran rekan pada pembelajaran kasus masukan kosong dan mengamati perubahan hasil kerja murid.","Mendokumentasikan keterbatasan uji coba agar tidak mengklaim pasti berhasil.","Menetapkan saran rekan sebagai standar seluruh kelas sebelum menilai kecocokannya dengan masalah murid."],"key":["A","C","D"],"why":"Pengembangan praktik harus reflektif, terbuka pada bukti, dan melindungi identitas murid.","section":"PCK","package":1,"uid":"p1-050","explanations":["Rubrik dan hasil anonim membantu rekan menelaah masalah pembelajaran pengujian tanpa membuka identitas murid.","Nilai dan kontak publik melampaui kebutuhan telaah praktik.","Uji pada kesulitan yang ditemukan memberi bukti apakah saran membantu murid merancang dan menjelaskan pengujian.","Keterbatasan membantu menilai jangkauan temuan secara proporsional.","Saran perlu ditelaah dan diuji dalam konteks kelas; penerapan langsung belum memberi dasar bahwa masalah pembelajaran tertangani."]},{"id":51,"code":"P.1","type":"PG","stem":"Guru IPS ingin siswa memahami perubahan lingkungan, menerapkan konsep pada lingkungan sekitar, lalu merefleksikan pilihan tindakannya. Rancangan terbaik adalah ...","options":["Meminta kutipan definisi sebagai satu-satunya bukti.","Mengadakan kuis istilah tentang lingkungan tanpa meminta hubungan hasilnya dengan pilihan tindakan murid.","Mengamati masalah, menganalisis konsep, mengusulkan tindakan, lalu merefleksikan pilihan.","Menilai banyaknya foto observasi sebagai bukti penerapan tanpa meminta penjelasan hubungan dengan konsep."],"key":"C","why":"Rancangan ini menyatukan pemahaman konsep, penerapan kontekstual, dan refleksi bermakna sebagaimana P.1.","section":"PU","package":1,"uid":"p1-051","explanations":["Kutipan definisi belum menunjukkan penerapan dan refleksi yang menjadi tujuan.","Kuis istilah belum menuntun keputusan dalam konteks sekitar.","Observasi, analisis, usulan, dan refleksi mencakup seluruh rangkaian tujuan.","Observasi dekat kehidupan perlu dihubungkan dengan konsep; banyak foto bukan bukti analisis."]},{"id":52,"code":"P.1","type":"Kategori","stem":"Setelah proyek pengurangan sampah kelas, sebagian murid dapat menyalin poster tetapi belum menghubungkan kegiatan dengan konsep yang dipelajari. Nilai tindak lanjut sebagai Tepat atau Tidak tepat.","options":["Menautkan kegiatan dengan tujuan yang jelas dan tantangan di kehidupan nyata.","Membuka ruang bagi siswa menjelaskan apa yang berubah dari pemahaman awalnya.","Membatasi keberhasilan pada selesai menyalin jawaban guru."],"key":["T","T","F"],"why":"Refleksi dan transfer menunjukkan pemahaman; reproduksi jawaban saja belum cukup.","section":"PU","package":1,"uid":"p1-052","explanations":["Tujuan dan masalah nyata membantu transfer dari kegiatan ke konsep.","Perubahan penjelasan memperlihatkan refleksi atas pemahaman awal.","Selesai menyalin belum menunjukkan konsep diterapkan dalam keputusan."]},{"id":53,"code":"P.1","type":"MCMA","stem":"Guru menemukan miskonsepsi pada konsep yang menjadi prasyarat pelajaran berikutnya. Strategi yang tepat adalah ... Pilih semua.","options":["Meminta siswa membandingkan gagasan awal dan hasil setelah eksplorasi.","Memberi nilai akhir hanya dari kecepatan menjawab.","Mengumpulkan jawaban awal untuk mengetahui penalaran siswa.","Memberi contoh pembanding yang menguji gagasan keliru.","Menolak pertanyaan karena mengganggu jadwal."],"key":["A","C","D"],"why":"Perubahan konsep dibantu diagnosis, bukti pembanding, dan refleksi pemahaman.","section":"PU","package":1,"uid":"p1-053","explanations":["Perbandingan gagasan awal dan akhir membantu perubahan konseptual.","Kecepatan saja tidak mengukur alasan dan perubahan pemahaman.","Jawaban awal mengungkap alasan di balik miskonsepsi.","Contoh pembanding memberi bukti untuk menguji gagasan keliru.","Menolak pertanyaan menutup sumber informasi kebutuhan belajar."]},{"id":54,"code":"P.2","type":"PG","stem":"Dalam satu kelas ada siswa dengan kemampuan membaca berbeda. Guru ingin semua memahami gagasan utama bacaan. Pilihan terbaik adalah ...","options":["Menambah waktu tanpa memeriksa hambatan membaca.","Memakai teks inti dan dukungan akses beragam sambil mengecek gagasan utama dengan sasaran sama.","Mengganti analisis gagasan utama dengan salinan judul.","Membagikan ringkasan berisi jawaban lalu menganggap salinan ringkasan sebagai bukti pemahaman mandiri murid."],"key":"B","why":"Kesetaraan tujuan dapat disertai variasi dukungan agar hambatan akses tidak menghalangi pencapaian.","section":"PU","package":1,"uid":"p1-054","explanations":["Tambahan waktu saja belum menanggapi hambatan kosakata atau representasi yang perlu diperiksa.","Dukungan berbeda tetap menuntut murid memahami gagasan utama tanpa mengganti sasaran.","Menyalin judul menurunkan tuntutan pemahaman bagi sebagian murid.","Salinan jawaban tidak menunjukkan murid dapat menemukan gagasan utama sendiri."]},{"id":55,"code":"P.2","type":"Kategori","stem":"Dalam diskusi untuk memahami gagasan utama bacaan, siswa memiliki latar bahasa beragam. Nilai tindakan berikut sebagai Tepat atau Tidak tepat.","options":["Menghentikan penjelasan gagasan untuk membetulkan setiap pelafalan yang sebenarnya sudah dipahami kelas.","Guru menganggap aksen berbeda sebagai tanda kemampuan berpikir rendah.","Guru memastikan istilah penting dipahami melalui contoh tanpa merendahkan bahasa rumah siswa."],"key":["F","F","T"],"why":"Pembelajaran responsif menghargai identitas bahasa sekaligus menjaga target akademik.","section":"PU","package":1,"uid":"p1-055","explanations":["Koreksi setiap pelafalan menghambat penyampaian gagasan yang sudah dapat dipahami, sementara tujuan diskusi bukan latihan pelafalan.","Aksen tidak menunjukkan tingkat kemampuan berpikir.","Contoh istilah membantu akses tanpa merendahkan bahasa rumah."]},{"id":56,"code":"P.2","type":"MCMA","stem":"Guru mengatur kerja kelompok dengan siswa yang berbeda kesiapan dan kebutuhan. Pilih keputusan yang tepat.","options":["Menyerahkan semua pekerjaan ke satu siswa yang dianggap pintar.","Mengecek secara berkala siapa yang belum mendapat kesempatan bicara.","Menyediakan kriteria tugas dan bantuan berjenjang.","Memberi label permanen kelompok pintar dan lemah.","Membagikan peran jelas dan kesempatan rotasi peran."],"key":["B","C","E"],"why":"Peran, pemantauan partisipasi, dan scaffolding mendukung keterlibatan seluruh siswa.","section":"PU","package":1,"uid":"p1-056","explanations":["Satu pelaksana menghilangkan kontribusi serta bukti anggota lain.","Pemantauan bicara membantu memperbaiki ketimpangan partisipasi.","Kriteria dan bantuan berjenjang memberi kejelasan dan dukungan.","Label tetap mengabaikan perkembangan dan menguatkan stigma.","Peran dan rotasi membagi kesempatan menunjukkan kemampuan."]},{"id":57,"code":"P.2","type":"PG","stem":"Siswa pindahan belum mengenal istilah teknis yang telah dipelajari kelas. Langkah awal paling tepat adalah ...","options":["Menyamakan tugas tanpa memeriksa prasyarat.","Mensyaratkan hafalan seluruh istilah sebelum diskusi.","Meminta teman menyelesaikan semua tugasnya.","Mengecek istilah yang belum dipahami melalui contoh singkat."],"key":"D","why":"Langkah awal ialah memetakan kesulitan istilah, bukan langsung menyamakan tugas, mensyaratkan seluruh hafalan, atau menyerahkan pekerjaan kepada teman. Dukungan dipilih setelah kebutuhan diketahui.","section":"PU","package":1,"uid":"p1-057","explanations":["Kesetaraan kesempatan memerlukan dukungan terhadap prasyarat yang belum dikenal.","Hafalan menyeluruh sebagai syarat partisipasi menghambat bantuan bertahap yang diperlukan.","Pengambilalihan tugas tidak memberi kesempatan atau bukti pemahaman murid pindahan.","Pemeriksaan awal memetakan istilah atau prasyarat yang perlu didukung; hasilnya menjadi dasar memilih glosarium dan bantuan berikutnya."]},{"id":58,"code":"P.3","type":"PG","stem":"Seorang siswa memberi jawaban salah dan beberapa teman tertawa. Guru sebaiknya ...","options":["Menghentikan ejekan, menghargai usaha, lalu meninjau alasan dan bukti secara aman.","Memindahkan pertanyaan ke murid tercepat tanpa membahas ejekan dan alasan jawaban yang semula keliru.","Menyatakan semua jawaban sama benarnya agar siswa merasa diterima tanpa meninjau ketepatan bukti.","Mengoreksi konsep dengan cepat tetapi menunda pembahasan ejekan sampai akhir semester agar jadwal tidak terganggu."],"key":"A","why":"Keamanan psikologis dan pembahasan alasan menciptakan ruang belajar yang berkesadaran dan menggembirakan.","section":"PU","package":1,"uid":"p1-058","explanations":["Respons ini memulihkan rasa aman sekaligus menjaga tuntutan penalaran dan ketepatan.","Pengalihan saja membiarkan ejekan serta miskonsepsi tidak ditanggapi.","Menghargai upaya tidak berarti menyamakan jawaban yang bertentangan dengan bukti.","Koreksi konsep saja belum memulihkan norma interaksi aman saat kejadian."]},{"id":59,"code":"P.3","type":"Kategori","stem":"Murid mengeluhkan permainan kuis sangat seru tetapi tidak mengetahui tujuan belajarnya. Guru akan merancang ulang kegiatan berkesadaran, bermakna, dan menggembirakan. Nilai gagasan berikut sebagai Tepat atau Tidak tepat.","options":["Pembelajaran menggembirakan selalu berarti tanpa tantangan akademik.","Aktivitas boleh menantang apabila ada dukungan, relevansi, dan suasana aman.","Siswa memahami tujuan belajar dan diberi ruang merefleksikan prosesnya."],"key":["F","T","T"],"why":"Kegembiraan belajar bukan hiburan semata; fokus, relevansi, tantangan yang terdukung, dan rasa aman bisa berjalan bersama.","section":"PU","package":1,"uid":"p1-059","explanations":["Kegembiraan tidak mengharuskan hilangnya tantangan akademik.","Tantangan dapat menyenangkan bila relevan, aman, dan didukung.","Tujuan dan refleksi membantu kesadaran atas proses belajar."]},{"id":60,"code":"P.4","type":"PG","stem":"Guru ingin siswa memakai AI untuk membuat rangkuman materi. Risiko utamanya ialah jawaban AI bisa keliru dan data siswa dapat terbuka. Langkah tepat adalah ...","options":["Memilih rangkuman dari kelancaran bahasa saja.","Mencocokkan klaim rangkuman dengan sumber tepercaya, membatasi data pribadi, dan meminta penjelasan dengan bahasa sendiri.","Menghapus nama saja lalu mengizinkan unggahan cerita keluarga yang masih dapat dikenali dari rincian kejadiannya.","Meminta dua layanan AI menghasilkan jawaban serupa dan menganggap kesepakatan itu telah cukup memverifikasi isi."],"key":"B","why":"Literasi digital meliputi verifikasi dan privasi, bukan hanya kemampuan menjalankan alat.","section":"PU","package":1,"uid":"p1-060","explanations":["Kelancaran bahasa tidak menjamin ketepatan isi rangkuman.","Pemeriksaan sumber, minimisasi data, dan penjelasan sendiri menanggapi dua risiko pada stimulus.","Cerita yang dapat dikenali tetap membuka informasi pribadi meskipun nama dihapus.","Kesepakatan keluaran AI dapat mengulang kekeliruan yang sama; sumber independen tetap dibutuhkan."]},{"id":61,"code":"P.4","type":"MCMA","stem":"Guru memilih media pembelajaran digital untuk kelas dengan akses beragam. Pertimbangan yang tepat adalah ... Pilih semua.","options":["Tampilan dan petunjuk dapat diakses oleh murid dengan beragam kebutuhan.","Selalu mewajibkan gawai spesifikasi tinggi walau banyak murid tidak memiliki.","Data murid yang diperlukan dibatasi sesuai tujuan.","Memilih media hanya karena sedang populer.","Tersedia versi berukuran ringan atau alternatif luring."],"key":["A","C","E"],"why":"Akses, inklusi, dan keamanan data menjadi dasar pemilihan TIK yang kritis.","section":"PU","package":1,"uid":"p1-061","explanations":["Petunjuk yang aksesibel menjaga partisipasi beragam kebutuhan.","Perangkat tinggi wajib menghalangi murid yang tidak memilikinya.","Pembatasan data mengurangi paparan yang tidak diperlukan.","Popularitas tidak membuktikan akses atau kesesuaian tujuan.","Versi ringan atau luring membantu murid dengan keterbatasan akses."]},{"id":62,"code":"P.5","type":"PG","stem":"Guru akan mengajar perbandingan dengan contoh kehidupan sekitar. Sebagian siswa belum akrab dengan konteks pasar tradisional. Pilihan terbaik adalah ...","options":["Menambah soal pasar tanpa menjelaskan istilah.","Menghapus seluruh konteks nyata dari pembelajaran.","Memakai beberapa konteks setara yang familier untuk menjelaskan perbandingan yang sama.","Mengelompokkan kemampuan secara tetap berdasarkan pengalaman pasar tanpa memeriksa penalaran perbandingan murid."],"key":"C","why":"Konteks beragam membantu transfer konsep tanpa mengasumsikan pengalaman semua siswa identik.","section":"PU","package":1,"uid":"p1-062","explanations":["Satu konteks yang tidak dipahami sebagian murid menghambat akses konsep.","Konteks nyata tetap berguna jika diberi dukungan atau alternatif.","Konteks setara memberi jalan berbeda menuju perbandingan yang sama.","Latar budaya tidak menentukan kemampuan yang tetap."]},{"id":63,"code":"P.5","type":"Kategori","stem":"Guru memilih bahan cerita lokal untuk latihan menyimpulkan bacaan. Sebagian murid belum mengenal tradisi dalam cerita tersebut. Nilai pertimbangan berikut sebagai Tepat atau Tidak tepat.","options":["Contoh lokal harus selalu dipakai meskipun menimbulkan stereotip kelompok tertentu.","Sumber lokal dipilih karena membantu mencapai tujuan dan dapat diakses murid.","Memilih cerita paling panjang tanpa mengecek istilah dan pengetahuan awal murid."],"key":["F","T","F"],"why":"Kontekstual bukan otomatis baik; guru perlu menjaga relevansi, akurasi, dan penghargaan pada keragaman.","section":"PU","package":1,"uid":"p1-063","explanations":["Stereotip tidak dibenarkan hanya karena suatu contoh bersifat lokal.","Sumber lokal bernilai bila relevan dengan tujuan dan terjangkau.","Panjang bahan tidak menjamin kesesuaian; istilah dan kesiapan perlu diperiksa."]},{"id":64,"code":"P.6","type":"PG","stem":"Di awal topik pecahan, guru memberi dua soal singkat untuk melihat apakah siswa memahami bagian dari keseluruhan. Informasi ini paling tepat dipakai untuk ...","options":["Memilih contoh dan dukungan dari diagnosis, lalu meninjau kelompok sesuai kemajuan.","Menetapkan kelompok tetap dari dua jawaban awal.","Memakai diagnosis sebagai nilai akhir pecahan.","Mencatat skor tanpa menyesuaikan pembelajaran."],"key":"A","why":"Asesmen awal dipakai untuk mengidentifikasi kebutuhan belajar, bukan memberi label atau hukuman.","section":"PU","package":1,"uid":"p1-064","explanations":["Diagnosis menuntun dukungan dan perlu ditinjau kembali dari perkembangan murid.","Bukti awal terbatas tidak membenarkan label kemampuan permanen.","Nilai awal tidak mewakili hasil setelah kesempatan pembelajaran.","Pencatatan saja belum memakai informasi untuk memenuhi kebutuhan belajar."]},{"id":65,"code":"P.6","type":"MCMA","stem":"Setelah exit ticket, guru mengetahui separuh kelas masih bingung menentukan alasan jawaban. Langkah tepat adalah ... Pilih semua.","options":["Mengelompokkan jawaban untuk mengidentifikasi pola kesalahan.","Memberi penjelasan/model tambahan yang menanggapi pola tersebut.","Mengajak siswa mengerjakan soal cek singkat untuk memastikan perbaikan.","Mengabaikan hasil karena materi sudah selesai diajarkan.","Mempermalukan siswa yang jawabannya belum tepat."],"key":["A","B","C"],"why":"Asesmen formatif bermakna jika hasilnya ditafsirkan dan digunakan untuk memperbaiki proses serta mengecek dampaknya.","section":"PU","package":1,"uid":"p1-065","explanations":["Pola kesalahan menuntun jenis bantuan yang diperlukan.","Model yang menanggapi pola memberi dukungan spesifik.","Cek ulang memberi bukti apakah tindak lanjut membantu.","Mengabaikan data membuat exit ticket tidak dipakai untuk pembelajaran.","Mempermalukan tidak memberi penjelasan atau bantuan yang dibutuhkan."]},{"id":66,"code":"P.6","type":"Kategori","stem":"Murid telah menyusun simpulan bacaan, tetapi satu bukti yang dipakai bertentangan dengan simpulannya. Guru ingin murid memperbaiki alasan secara mandiri. Nilai umpan balik berikut sebagai Tepat atau Tidak tepat.","options":["“Bandingkan jawabanmu dengan rubrik, revisi satu bagian, lalu jelaskan mengapa diubah.”","“Kamu memang tidak berbakat; jangan mencoba soal ini lagi.”","“Alasanmu sudah menyebut dua bukti; cek lagi apakah bukti ketiga mendukung simpulanmu.”"],"key":["T","F","T"],"why":"Umpan balik yang baik spesifik, menjaga martabat, dan menyebut langkah perbaikan yang dapat dilakukan.","section":"PU","package":1,"uid":"p1-066","explanations":["Rubrik, revisi, dan alasan perubahan memberi tindak lanjut yang dapat diamati.","Label tidak berbakat bersifat menghakimi dan tidak memberi langkah perbaikan.","Komentar menunjukkan kemajuan serta lokasi bukti yang perlu ditinjau."]},{"id":67,"code":"P.6","type":"PG","stem":"Hasil penilaian akhir memperlihatkan banyak siswa belum mencapai satu indikator. Tindakan guru berikutnya yang paling bertanggung jawab adalah ...","options":["Menutup tindak lanjut setelah nilai terbit dan memakai materi berikutnya tanpa memeriksa indikator yang lemah.","Mengurangi tuntutan soal berikutnya tanpa pembelajaran tambahan agar jumlah murid mencapai nilai target meningkat.","Menyimpan rincian hasil hanya untuk guru sehingga murid tidak mengetahui indikator yang perlu diperbaiki.","Menganalisis indikator lemah dan menyiapkan dukungan serta kesempatan perbaikan."],"key":"D","why":"Hasil asesmen digunakan untuk keputusan pembelajaran dan tindak lanjut, bukan sekadar angka akhir.","section":"PU","package":1,"uid":"p1-067","explanations":["Nilai terbit tidak mengakhiri tanggung jawab mendukung capaian.","Soal lebih mudah tanpa pembelajaran dapat menyamarkan kesulitan.","Menyembunyikan hasil menghambat murid memahami kebutuhan perbaikan.","Analisis indikator dan dukungan lanjutan menghubungkan hasil dengan kesempatan belajar."]},{"id":68,"code":"K.1","type":"PG","stem":"Seorang murid menceritakan sedang mengalami masalah keluarga dan meminta tidak diumumkan. Respons guru yang paling etis adalah ...","options":["Mengumumkan identitas agar teman memberi dukungan.","Mendengar secara empatik, menjaga privasi, dan merujuk proporsional bila ada risiko keselamatan.","Membagikan seluruh rincian ke grup guru tanpa menentukan siapa yang perlu terlibat dalam perlindungan murid.","Menjanjikan kerahasiaan mutlak dan mengabaikan tanda bahaya karena murid meminta cerita tidak diumumkan."],"key":"B","why":"Etika menuntut empati dan privasi; jika terdapat risiko keselamatan, guru mengikuti prosedur perlindungan dan rujukan yang tepat.","section":"PU","package":1,"uid":"p1-068","explanations":["Nama dan cerita publik melanggar kepercayaan serta privasi.","Kerahasiaan dijaga dengan pengecualian proporsional untuk perlindungan sesuai prosedur.","Grup luas tanpa kebutuhan bukan rujukan yang proporsional.","Tanda bahaya perlu ditindaklanjuti, bukan diabaikan atas nama privasi."]},{"id":69,"code":"K.1","type":"Kategori","stem":"Guru mendapati penilaiannya keliru dan mendapat permintaan menaikkan nilai kerabat tanpa bukti tugas tambahan. Nilai respons berikut sebagai Tepat atau Tidak tepat.","options":["Guru meninjau kembali nilai memakai kriteria yang sudah disampaikan sebelum tugas.","Guru mengakui kekeliruan penilaian, memperbaikinya berdasarkan bukti, dan menyampaikan koreksi kepada pihak terkait.","Guru menaikkan nilai murid tertentu karena kedekatan pribadi tanpa bukti belajar."],"key":["T","T","F"],"why":"Keteladanan ditunjukkan oleh keadilan, integritas, dan tanggung jawab memperbaiki kesalahan.","section":"PU","package":1,"uid":"p1-069","explanations":["Peninjauan memakai kriteria yang sama menjaga keadilan saat memperbaiki kesalahan penilaian.","Koreksi berbasis bukti dan komunikasi kepada pihak terkait menunjukkan integritas serta tanggung jawab atas penilaian.","Kedekatan pribadi tidak menjadi bukti capaian belajar."]},{"id":70,"code":"K.2","type":"PG","stem":"Setelah proyek kelompok gagal mencapai target, guru merasa metode yang dipilih tidak efektif. Refleksi profesional paling tepat adalah ...","options":["Menyimpulkan murid tidak cocok bekerja kelompok.","Mengganti anggota saja tanpa meninjau proses.","Menelaah bukti dan umpan balik murid, lalu menguji satu perbaikan yang beralasan.","Mengganti semua kegiatan dengan metode populer sebelum menemukan bagian proses yang menghambat ketercapaian target."],"key":"C","why":"Refleksi diri berbasis bukti mendukung pola pikir bertumbuh dan peningkatan praktik.","section":"PU","package":1,"uid":"p1-070","explanations":["Satu kegagalan belum membuktikan karakter murid menjadi penyebab.","Komposisi baru belum menanggapi kemungkinan hambatan instruksi, peran, atau kriteria.","Bukti dan umpan balik mengarahkan perubahan yang dapat dievaluasi dampaknya.","Pergantian metode tanpa diagnosis belum merupakan refleksi berbasis bukti."]},{"id":71,"code":"K.2","type":"MCMA","stem":"Guru ingin mengembangkan kompetensi secara berkelanjutan. Mana yang mencerminkan growth mindset profesional? Pilih semua.","options":["Mencoba strategi baru secara terukur dan membandingkan buktinya.","Menganggap kritik berarti dirinya bukan guru yang baik sehingga menolak masukan.","Berdiskusi dengan rekan dan menyesuaikan praktik dari temuan.","Mengklaim dirinya sudah tidak perlu belajar karena telah lulus pendidikan guru.","Mencatat satu aspek pembelajaran yang perlu diperbaiki dari umpan balik."],"key":["A","C","E"],"why":"Pola pikir bertumbuh tampak dalam penerimaan masukan, eksperimen terukur, dan tindak lanjut hasil refleksi.","section":"PU","package":1,"uid":"p1-071","explanations":["Percobaan terukur memungkinkan guru belajar dari hasil.","Kritik terhadap praktik tidak sama dengan vonis identitas guru.","Diskusi dan adaptasi menghubungkan masukan dengan perbaikan.","Kelulusan tidak mengakhiri kebutuhan belajar profesional.","Umpan balik yang ditindaklanjuti menjadi dasar perkembangan diri."]},{"id":72,"code":"K.3","type":"PG","stem":"Dalam diskusi kelas, hanya beberapa siswa berani berbicara. Guru ingin membangun budaya belajar saling mendukung. Langkah terbaik adalah ...","options":["Memberi label tidak aktif dari frekuensi bicara.","Menegur murid acak yang belum siap menjawab.","Membiarkan dominasi agar diskusi cepat selesai.","Menyepakati aturan diskusi, waktu berpikir, dan giliran berbagi yang aman."],"key":"D","why":"Keputusan guru perlu konsisten membangun partisipasi dan rasa aman untuk mengembangkan potensi semua murid.","section":"PU","package":1,"uid":"p1-072","explanations":["Pelabelan dari frekuensi bicara mengabaikan kesempatan dan hambatan murid untuk berpartisipasi.","Menegur ketidaksiapan sebelum memberi waktu berpikir belum mengatasi hambatan partisipasi.","Dominasi tetap tidak memberi kesempatan berkembang bagi yang lain.","Waktu berpikir dan giliran aman membangun partisipasi yang konsisten."]},{"id":73,"code":"K.3","type":"Kategori","stem":"Dalam satu semester, beberapa murid berhenti mencoba setelah mendapat peringkat rendah. Guru ingin membangun kebiasaan perbaikan yang konsisten. Nilai keputusan berikut sebagai Tepat atau Tidak tepat.","options":["Menetapkan kelompok ranking rendah tetap selama setahun agar dukungan tidak perlu ditinjau lagi.","Menilai perkembangan hanya dari perubahan peringkat meskipun capaian kriteria belajar murid meningkat.","Guru memberi kesempatan revisi tugas berdasarkan kriteria yang jelas."],"key":["F","F","T"],"why":"Budaya belajar positif menekankan perkembangan, standar yang jelas, dan peluang belajar dari kesalahan.","section":"PU","package":1,"uid":"p1-073","explanations":["Kelompok tetap dari ranking mengabaikan kemajuan dan kebutuhan yang berubah.","Peringkat menunjukkan posisi relatif; peringkat yang tetap tidak meniadakan peningkatan capaian kriteria belajar.","Revisi dengan kriteria memberi jalur nyata untuk memperbaiki capaian."]},{"id":74,"code":"S.1","type":"PG","stem":"Orang tua menghubungi guru karena anaknya merasa tidak dipahami di kelas. Respons komunikasi paling tepat adalah ...","options":["Menjelaskan aturan kelas lebih dahulu lalu menutup percakapan tanpa meminta kejadian yang dialami anak.","Mendengarkan, mengklarifikasi kejadian dan bukti, lalu menyepakati tindak lanjut.","Memindahkan pembahasan masalah anak ke grup kelas agar seluruh wali dapat menilai siapa yang benar.","Menjanjikan perubahan nilai anak untuk meredakan keberatan sebelum memeriksa pengalaman dan bukti belajarnya."],"key":"B","why":"Komunikasi inklusif dan empatik mencari pemahaman bersama dan tindakan yang berbasis informasi.","section":"PU","package":1,"uid":"p1-074","explanations":["Penjelasan sepihak tidak cukup memahami pengalaman yang memicu kekhawatiran.","Mendengar dan mengklarifikasi bukti memungkinkan komunikasi empatik dengan tindakan yang beralasan.","Pembahasan ke grup memperluas paparan masalah pribadi tanpa kebutuhan.","Janji nilai sebelum pemeriksaan tidak menjawab persoalan pemahaman dan mengabaikan bukti penilaian."]},{"id":75,"code":"S.1","type":"MCMA","stem":"Guru memberi umpan balik kepada siswa yang berbeda latar bahasa dan gaya komunikasi. Cara yang tepat adalah ... Pilih semua.","options":["Menggunakan kalimat jelas dan contoh spesifik.","Meminta murid menjelaskan kembali langkah perbaikan dan memberi kesempatan bertanya.","Mengejek pengucapan bahasa siswa.","Menyediakan saluran tertulis/visual bila membantu komunikasi.","Memotong penjelasan siswa karena lambat menyampaikan ide."],"key":["A","B","D"],"why":"Umpan balik inklusif menyesuaikan cara komunikasi sambil menghargai martabat dan kebutuhan murid.","section":"PU","package":1,"uid":"p1-075","explanations":["Kalimat dan contoh spesifik memperjelas pesan perbaikan.","Penjelasan kembali memberi bukti apakah murid memahami langkah perbaikan; kesempatan bertanya membantu mengklarifikasi bagian yang belum jelas.","Ejekan pengucapan menstigma latar bahasa.","Saluran visual atau tertulis membantu kebutuhan komunikasi tertentu.","Memotong penjelasan menghilangkan informasi dan partisipasi murid."]},{"id":76,"code":"S.2","type":"PG","stem":"Seorang siswa sering absen sehingga tertinggal tugas. Guru mata pelajaran belum memahami penyebabnya. Langkah kolaboratif paling tepat adalah ...","options":["Meminta tugas selesai sebelum mencari sebab absen.","Mengirim rincian masalah ke seluruh wali murid agar memperoleh dukungan luas meskipun kebutuhannya belum dipetakan.","Berkoordinasi dengan wali kelas dan/atau guru BK secara proporsional, mendengar murid dan keluarga, lalu menyusun dukungan.","Menetapkan nilai nol untuk seluruh tugas tertinggal dan menutup kesempatan perbaikan sebelum alasan absen diketahui."],"key":"C","why":"Kolaborasi dengan pihak terkait memetakan hambatan dan merancang dukungan, tetap menjaga privasi.","section":"PU","package":1,"uid":"p1-076","explanations":["Tuntutan tugas sebelum memetakan penyebab belum memberi dasar dukungan yang sesuai.","Penyebaran ke semua wali tidak proporsional dan membuka informasi pribadi yang tidak diperlukan.","Pihak terkait memetakan hambatan bersama dan menyepakati dukungan dengan tetap menjaga privasi.","Keputusan permanen sebelum memahami penyebab menutup kesempatan tindak lanjut belajar."]},{"id":77,"code":"S.2","type":"Kategori","stem":"Sekolah dan wali murid merancang dukungan untuk seorang murid yang sering tertinggal tugas. Nilai praktik kolaborasi berikut sebagai Tepat atau Tidak tepat.","options":["Mengalihkan seluruh tanggung jawab bantuan kepada keluarga tanpa menyepakati peran sekolah.","Guru berbagi perkembangan belajar yang relevan melalui jalur komunikasi yang tepat.","Guru menyebarkan data pribadi murid kepada semua orang tua agar transparan."],"key":["F","T","F"],"why":"Kolaborasi memerlukan komunikasi terarah dan perlindungan kerahasiaan data murid.","section":"PU","package":1,"uid":"p1-077","explanations":["Kolaborasi perlu peran bersama; pengalihan sepihak menghilangkan tanggung jawab sekolah.","Informasi perkembangan yang relevan membantu pihak terkait merencanakan dukungan.","Transparansi tidak berarti semua orang tua berhak atas data murid lain."]},{"id":78,"code":"S.3","type":"PG","stem":"Komunitas guru membahas cara meningkatkan keterlibatan siswa dalam diskusi. Kontribusi paling bermanfaat adalah ...","options":["Membagikan praktik dan bukti, menerima masukan, lalu menguji perbaikan sesuai konteks.","Membagikan materi rekan tanpa atribusi.","Menganjurkan satu strategi untuk semua sekolah.","Mengirim daftar kegiatan tanpa bukti hasil dan menolak peninjauan masukan karena metode tersebut pernah dipakai."],"key":"A","why":"Komunitas pembelajaran berguna ketika praktik, bukti, dan refleksi dibagikan secara bertanggung jawab.","section":"PU","package":1,"uid":"p1-078","explanations":["Kontribusi bukti dan tindak lanjut menjadikan komunitas tempat belajar profesional bersama.","Materi rekan perlu dibagikan dengan atribusi yang sesuai; penghilangan atribusi tidak menunjukkan kontribusi profesional yang bertanggung jawab.","Satu konteks tidak cukup mendukung penerapan universal.","Daftar aktivitas tanpa bukti dan refleksi sulit dipakai untuk menilai atau memperbaiki praktik."]},{"id":79,"code":"PF.1","type":"PG","stem":"Guru menilai proyek lintas mata pelajaran. Hasil belajar paling menggambarkan tujuan pendidikan yang luas adalah ...","options":["Menghasilkan produk sesuai contoh dan menjelaskan langkah kerja, tetapi belum menerapkannya pada masalah baru.","Mencapai angka tinggi tanpa bukti penerapan.","Menyelesaikan cepat tanpa alasan dan tanggung jawab.","Menalar, bekerja sama secara etis, dan menerapkan pengetahuan pada masalah bermakna."],"key":"D","why":"Tujuan pendidikan mencakup penguasaan pengetahuan, karakter, kolaborasi, dan penerapan yang bertanggung jawab.","section":"PU","package":1,"uid":"p1-079","explanations":["Produk dan penjelasan langkah menunjukkan sebagian capaian, tetapi belum menunjukkan penerapan pada masalah baru sebagaimana tujuan pendidikan yang lebih luas.","Angka saja belum memberi bukti penerapan pengetahuan, karakter, dan kolaborasi.","Kecepatan tanpa penalaran dan tanggung jawab belum menunjukkan tujuan pendidikan secara utuh.","Penalaran, etika, kolaborasi, dan penerapan memberi bukti hasil pendidikan yang lebih lengkap."]},{"id":80,"code":"P.5","type":"MCMA","stem":"Dalam proyek lingkungan, murid harus mencatat pengamatan, membandingkan data, dan menarik simpulan. Alat sekolah terbatas. Pilih adaptasi sumber belajar yang tetap mendukung tujuan tersebut.","options":["Menggunakan pengamatan lingkungan setempat dengan prosedur aman dan data yang dapat dicatat.","Menyediakan format pencatatan sederhana dan contoh analisis data.","Menghapus kompetensi analisis karena alat laboratorium terbatas.","Membandingkan hasil dengan konsep ilmiah dan membahas keterbatasan pengamatan.","Memaksakan alat yang tidak aman demi meniru sekolah lain."],"key":["A","B","D"],"why":"Pengamatan setempat yang aman menyediakan sumber data; format pencatatan dan contoh analisis membantu mengolahnya. Membandingkan hasil dengan konsep serta membahas keterbatasan menjaga ketepatan simpulan. Tujuan analisis tidak dihapus karena alat terbatas.","section":"PU","package":1,"uid":"p1-080","explanations":["Pengamatan aman dengan prosedur jelas memberi data lokal yang dapat dianalisis.","Format sederhana dan contoh membantu mengatasi kebutuhan prasyarat analisis.","Keterbatasan alat tidak otomatis mengharuskan penghapusan tujuan analisis.","Konsep dan batas data membantu murid menarik simpulan yang proporsional.","Meniru alat berisiko mengorbankan keselamatan tanpa keharusan pedagogis."]}]}],"legacyQuestions":[{"id":1,"code":"P.1","type":"PG","stem":"Dalam rancangan ERD perpustakaan kelas, beberapa murid menjadikan nama siswa sebagai primary key karena setiap murid punya nama. Guru menemukan dua murid bernama Nisa. Tindakan pembelajaran yang paling tepat adalah ...","options":["Memberi definisi primary key untuk dicatat lalu meminta murid lanjut menggambar.","Memperlihatkan dua rekaman bernama Nisa, mengajak murid menguji identitas unik, lalu merevisi rancangan dengan ID siswa.","Langsung mengganti semua nama menjadi nomor urut tanpa diskusi.","Menghapus salah satu rekaman Nisa agar tidak ada duplikasi."],"key":"B","why":"Pertentangan data nyata mengungkap miskonsepsi: nama tidak menjamin keunikan, sedangkan ID siswa dapat menjadi PK. Guru membantu murid menemukan alasan sebelum memperbaiki ERD.","section":"PCK"},{"id":2,"code":"P.1","type":"MCMA","stem":"Kelompok merancang basis data peminjaman alat lab. Guru ingin menghubungkan konsep relasi satu-ke-banyak dengan implementasi SQL. Aktivitas mana yang paling mendukung? Pilih semua jawaban yang tepat.","options":["Meminta murid menyalin definisi foreign key berulang kali.","Membuat contoh satu siswa yang memiliki beberapa peminjaman.","Mengabaikan tabel referensi agar latihan lebih singkat.","Menempatkan id_siswa pada tabel peminjaman dan menguji data yang terhubung.","Meminta murid menjelaskan dampak jika id_siswa pada peminjaman tidak merujuk siswa yang ada."],"key":["B","D","E"],"why":"B, D, E menghubungkan kardinalitas, implementasi FK, dan integritas referensial. Menyalin definisi atau menghilangkan referensi tidak memfasilitasi pemahaman.","section":"PCK"},{"id":3,"code":"P.1","type":"PG","stem":"Murid membuat formulir Laravel yang bisa dikirim walaupun kolom email kosong. Mereka menyimpulkan atribut required di HTML saja pasti cukup menjaga validitas data. Cara paling tepat meluruskan konsep adalah ...","options":["Menyuruh murid menghafal semua aturan validasi Laravel.","Mengganti framework agar validasi otomatis sempurna.","Mendemonstrasikan pengiriman request yang melewati validasi browser, lalu membimbing penerapan validasi sisi server.","Menganggap hasilnya benar selama tampilan formulir rapi."],"key":"C","why":"Validasi browser membantu pengalaman pengguna, tetapi pemeriksaan data tetap diperlukan di server. Demonstrasi request memperlihatkan alasan teknisnya.","section":"PCK"},{"id":4,"code":"P.1","type":"Kategori","stem":"Guru memakai dua tabel kecil, siswa dan peminjaman, untuk membangun pemahaman JOIN. Nilai tiap tindakan sebagai Tepat atau Tidak tepat.","options":["Murid memprediksi hasil JOIN sebelum menjalankan query, lalu membandingkan prediksi dengan keluaran.","Guru langsung memberikan query jadi tanpa membahas relasi tabel.","Murid menjelaskan mengapa baris tertentu muncul atau tidak muncul dalam hasil INNER JOIN."],"key":["T","F","T"],"why":"Prediksi, uji, dan penjelasan hasil membangun model mental. Query yang hanya disalin dapat menghasilkan keluaran tanpa pemahaman relasi.","section":"PCK"},{"id":5,"code":"P.1","type":"PG","stem":"Saat mengenalkan objek dalam pemrograman berorientasi objek, murid menyamakan class dan object. Representasi awal mana yang paling membantu?","options":["Membandingkan class dengan rancangan atribut/perilaku dan object dengan dua instans nyata berbeda.","Meminta murid langsung membuat aplikasi kompleks tanpa contoh.","Mengatakan class dan object identik agar mudah diingat.","Menunda pembahasan hingga ujian akhir."],"key":"A","why":"Contoh dua objek dari satu class membedakan cetak biru dan instans sambil mempertahankan keterkaitan konsep dengan kode.","section":"PCK"},{"id":6,"code":"P.1","type":"MCMA","stem":"Kelompok belajar kolaborasi Git pada proyek website kelas. Bukti pemahaman alur kerja yang layak diminta guru adalah ... Pilih semua yang tepat.","options":["Mengumpulkan satu file ZIP terakhir tanpa riwayat perubahan.","Memperlihatkan commit dengan pesan yang menjelaskan perubahan.","Menjelaskan kapan sebuah branch perlu digabung dan bagaimana menangani konflik.","Memastikan semua murid memakai satu akun agar mudah.","Menjelaskan perubahan lewat perbandingan diff pada dua versi kode."],"key":["B","C","E"],"why":"Commit, branch/merge, dan diff merupakan bukti proses version control; satu file ZIP atau satu akun bersama menghilangkan jejak kontribusi.","section":"PCK"},{"id":7,"code":"P.1","type":"PG","stem":"Pada kasus transaksi koperasi sekolah, setiap transaksi bisa berisi banyak jenis barang. Murid membuat satu kolom barang1, barang2, barang3 pada tabel transaksi. Pertanyaan pemantik terbaik adalah ...","options":["“Kenapa kalian tidak memilih nama kolom lebih pendek?”","“Siapa yang paling cepat bisa menghafal SQL?”","“Bagaimana jika satu transaksi memuat enam barang dan jumlah tiap barang berbeda?” lalu mengarahkan ke tabel detail_transaksi.","“Maukah kalian menghapus transaksi yang berisi banyak barang?”"],"key":"C","why":"Kasus enam barang menonjolkan keterbatasan kolom berulang dan kebutuhan tabel detail yang terhubung dengan transaksi serta barang.","section":"PCK"},{"id":8,"code":"P.1","type":"Kategori","stem":"Guru mengajar perulangan dengan tabel pelacakan nilai variabel. Nilai tindakan sebagai Tepat atau Tidak tepat.","options":["Mengajak murid menelusuri nilai variabel pada setiap iterasi sebelum menjalankan program.","Menilai jawaban benar dari keluaran akhir saja tanpa memeriksa alasan murid.","Membandingkan pelacakan manual dengan keluaran program lalu membahas selisihnya."],"key":["T","F","T"],"why":"Trace table membantu menjelaskan keadaan program, bukan hanya hasil akhir. Membandingkan hasil merupakan kesempatan refleksi.","section":"PCK"},{"id":9,"code":"P.2","type":"PG","stem":"Asesmen awal menunjukkan sebagian murid sudah lancar SELECT-WHERE, sebagian belum mengenal kondisi WHERE. Strategi paling responsif adalah ...","options":["Memberikan tugas identik dengan target waktu sama untuk semuanya.","Membagi dukungan dan tingkat tantangan secara fleksibel sesuai bukti awal, dengan tujuan belajar inti yang sama.","Memindahkan murid yang belum lancar ke luar kelas.","Hanya menunjuk murid paling cepat untuk menjawab."],"key":"B","why":"Diferensiasi menyesuaikan jalan menuju tujuan yang sama berdasarkan kebutuhan nyata; bukan pelabelan kelompok tetap.","section":"PCK"},{"id":10,"code":"P.2","type":"Kategori","stem":"Di laboratorium, empat murid belum mendapat komputer. Nilai keputusan guru sebagai Tepat atau Tidak tepat.","options":["Menyusun giliran operator, penguji, dan pencatat sehingga semua berperan dan berganti peran.","Memberikan penilaian keterampilan komputer hanya kepada murid yang kebagian perangkat.","Menyiapkan tugas prediksi query atau rancangan ERD saat menunggu giliran praktik."],"key":["T","F","T"],"why":"Rotasi dan tugas tanpa perangkat menjaga partisipasi serta kesempatan menunjukkan capaian. Penilaian harus adil terhadap akses.","section":"PCK"},{"id":11,"code":"P.2","type":"MCMA","stem":"Salah satu murid memiliki kendala penglihatan dan kesulitan membaca tangkapan layar kode yang kecil. Penyesuaian apa yang tepat? Pilih semua.","options":["Menyediakan teks kode yang dapat diperbesar atau dibaca pembaca layar.","Mengurangi target menjadi hanya menonton teman tanpa kontribusi.","Memastikan kontras dan keterbacaan bahan praktik.","Mengizinkan alternatif cara menjelaskan logika program selama mengukur tujuan yang sama.","Mengecualikan murid dari asesmen agar tidak kesulitan."],"key":["A","C","D"],"why":"Penyesuaian akses dan cara respons dapat menjaga target kompetensi. Menghapus kesempatan praktik atau asesmen bukan pilihan inklusif.","section":"PCK"},{"id":12,"code":"P.2","type":"PG","stem":"Murid yang cepat selesai CRUD mulai tidak tertantang, sementara teman lain masih membuat tabel. Tindakan terbaik adalah ...","options":["Memberikan tantangan lanjutan validasi dan uji kasus batas, sambil menyediakan bantuan bertahap bagi yang masih kesulitan.","Menjadikan murid cepat selesai sebagai pengganti guru sepanjang jam.","Menghentikan kegiatan semua murid sampai seluruh kelas sama cepat.","Memberi tugas menyalin ulang kode tanpa tujuan baru."],"key":"A","why":"Tantangan pengayaan dan scaffolding disesuaikan kesiapan. Tutor sebaya boleh membantu, tetapi tidak menggantikan tanggung jawab guru.","section":"PCK"},{"id":13,"code":"P.2","type":"PG","stem":"Dalam diskusi ERD ada murid yang sulit mengikuti penjelasan lisan di ruang bising. Respons guru yang paling tepat adalah ...","options":["Menganggap murid tidak fokus dan menegur di depan kelas.","Menambah volume bicara saja tanpa melihat hambatan.","Memberikan instruksi tertulis/visual, memastikan posisi dan akses komunikasi, serta mengecek pemahaman secara pribadi.","Membebaskan murid dari tujuan pembelajaran."],"key":"C","why":"Akses multimodal dan pengecekan pemahaman membuat murid dapat ikut tanpa distigma.","section":"PCK"},{"id":14,"code":"P.3","type":"PG","stem":"Saat latihan debugging banyak murid malu karena error. Guru ingin kelas aman untuk mencoba. Respons terbaik adalah ...","options":["Mengumumkan siapa paling banyak error.","Menunjukkan contoh error dari kode sederhana, menormalisasi revisi, dan meminta murid menjelaskan langkah diagnosis.","Menghapus latihan debugging dari kegiatan.","Menghitung semua error sebagai pelanggaran tata tertib."],"key":"B","why":"Menormalisasi kesalahan sebagai bukti proses belajar dan mengajarkan strategi diagnosis mendukung keberanian bereksperimen.","section":"PCK"},{"id":15,"code":"P.3","type":"Kategori","stem":"Guru menyiapkan proyek pencatatan peminjaman kelas. Nilai praktik berikut sebagai Tepat atau Tidak tepat.","options":["Membuka pembelajaran dengan masalah yang dekat dengan kebutuhan murid dan menjelaskan alasan mempelajarinya.","Mewajibkan setiap kelompok menghias slide tanpa menguji fungsi database.","Mengakhiri proyek dengan refleksi keputusan desain, kendala, dan perbaikan."],"key":["T","F","T"],"why":"Pembelajaran bermakna menghubungkan tujuan, pengalaman, dan refleksi; hiasan bukan bukti capaian teknis.","section":"PCK"},{"id":16,"code":"P.3","type":"MCMA","stem":"Guru ingin suasana diskusi kode menyenangkan tetapi tetap menantang. Pilih praktik yang tepat.","options":["Mengizinkan kelompok menjelaskan alternatif solusi tanpa diejek.","Menyebut kode murid tertentu “paling bodoh” sebagai humor.","Memberi kriteria keberhasilan yang jelas dan kesempatan memperbaiki produk.","Memuji proses pengujian dan argumentasi, bukan hanya jawaban tercepat.","Mewajibkan semua murid meniru satu cara tanpa berdiskusi."],"key":["A","C","D"],"why":"Keamanan psikologis, kesempatan revisi, dan penghargaan atas alasan membangun keterlibatan tanpa menurunkan standar.","section":"PCK"},{"id":17,"code":"P.3","type":"PG","stem":"Menjelang akhir sesi SQL, murid mulai kehilangan fokus. Pilihan yang tetap bermakna adalah ...","options":["Memberi ceramah baru selama 30 menit tanpa interaksi.","Menutup pelajaran lebih awal tanpa asesmen.","Meminta murid menyalin definisi JOIN sebanyak sepuluh kali.","Melakukan tantangan singkat: prediksi query, uji di DB, lalu simpulkan satu temuan dan satu pertanyaan."],"key":"D","why":"Aktivitas singkat yang mengaktifkan prediksi–uji–refleksi memulihkan keterlibatan sekaligus memeriksa pemahaman.","section":"PCK"},{"id":18,"code":"P.4","type":"PG","stem":"Murid menggunakan AI untuk membuat kode autentikasi dan menganggap hasilnya pasti aman. Guru sebaiknya ...","options":["Melarang pembicaraan tentang AI selamanya.","Meminta murid menguji dan menjelaskan kode, memeriksa pengelolaan sandi serta input, dan mendiskusikan keterbatasan keluaran AI.","Memberi nilai penuh karena aplikasi berhasil dijalankan.","Membagikan kredensial server sekolah ke AI untuk meminta perbaikan."],"key":"B","why":"Literasi AI mencakup verifikasi fungsi, keamanan, sumber data, dan tanggung jawab penggunaan.","section":"PCK"},{"id":19,"code":"P.4","type":"Kategori","stem":"Guru memakai platform daring untuk penugasan RPL. Nilai keputusan berikut sebagai Tepat atau Tidak tepat.","options":["Menyiapkan alternatif akses saat jaringan atau perangkat murid terbatas.","Mengunggah data identitas siswa asli ke layanan publik agar contoh terlihat realistis.","Memilih alat berdasarkan kontribusinya terhadap tujuan belajar, bukan popularitasnya."],"key":["T","F","T"],"why":"Penggunaan TIK perlu mempertimbangkan akses, privasi, dan kesesuaian tujuan, bukan semata fitur.","section":"PCK"},{"id":20,"code":"P.4","type":"MCMA","stem":"Saat internet lab tidak stabil, guru tetap ingin murid mempelajari hubungan tabel. Pilih alternatif yang tepat.","options":["Menggunakan kartu entitas dan atribut untuk memodelkan relasi secara luring.","Menunggu internet pulih tanpa aktivitas belajar apa pun.","Menyiapkan skrip SQL lokal atau dataset contoh yang bisa dijalankan tanpa internet.","Menggunakan kertas untuk memprediksi hasil JOIN, lalu menguji saat perangkat siap.","Menghapus tujuan belajar hari itu selamanya."],"key":["A","C","D"],"why":"Model fisik, SQL lokal, dan prediksi kertas tetap menargetkan konsep yang sama meski koneksi tidak tersedia.","section":"PCK"},{"id":21,"code":"P.4","type":"PG","stem":"Guru hendak memilih aplikasi gambar ERD daring. Murid mampu menggambar ERD di kertas. Prinsip pilihan paling tepat adalah ...","options":["Gunakan aplikasi apa pun asalkan paling ramai dipakai.","Teknologi wajib digunakan di setiap tahap meskipun waktu terbuang untuk registrasi.","Pilih alat apabila membantu menguji relasi, merevisi rancangan, atau kolaborasi; kertas tetap sah bila mencapai tujuan.","Hanya hasil digital yang boleh dinilai."],"key":"C","why":"Teknologi alat, bukan tujuan. Pilihan didasarkan pada nilai tambah pedagogis dan kondisi akses.","section":"PCK"},{"id":22,"code":"P.4","type":"PG","stem":"Sebuah generator kode AI menghasilkan query yang menampilkan informasi pribadi siswa tanpa pembatasan. Tugas belajar yang paling tepat adalah ...","options":["Membandingkan keluaran dengan kebutuhan dan prinsip akses data, lalu merancang query yang hanya menampilkan informasi yang diperlukan.","Menggunakan query itu apa adanya karena dapat dijalankan.","Mempublikasikan hasil query agar mudah dinilai.","Menghapus topik keamanan data dari silabus."],"key":"A","why":"Kritik terhadap keluaran otomatis menuntut pemahaman kebutuhan, minimisasi data, dan pengujian hasil.","section":"PCK"},{"id":23,"code":"P.5","type":"PG","stem":"Guru ingin memberi tugas rancangan basis data yang dekat dengan kehidupan murid. Masalah peminjaman alat olahraga sekolah tersedia dan datanya bisa disimulasikan. Kegiatan terbaik adalah ...","options":["Memilih kasus industri yang rumit walaupun murid belum memahami entitas.","Menyalin rancangan dari internet tanpa memahami kebutuhan.","Membiarkan murid menggambar tabel sesuka hati tanpa spesifikasi.","Mengobservasi kebutuhan peminjaman, menyusun entitas-relasi, dan menguji rancangan dengan contoh transaksi."],"key":"D","why":"Kebutuhan lokal yang konkret dapat menghubungkan konsep ERD, relasi, dan validasi rancangan.","section":"PCK"},{"id":24,"code":"P.5","type":"Kategori","stem":"Guru mengadaptasi studi kasus untuk SMK. Nilai keputusan berikut sebagai Tepat atau Tidak tepat.","options":["Memakai contoh proses koperasi setempat tanpa menganggap semua murid memiliki pengalaman yang sama.","Memilih konteks hanya karena tren walaupun tidak mendukung kompetensi yang dinilai.","Mengajak murid menyebutkan contoh alur data lain yang setara bila pengalaman awal berbeda."],"key":["T","F","T"],"why":"Konteks lokal membantu jika relevan dan membuka beragam pengalaman; guru tidak boleh berasumsi semua murid sama.","section":"PCK"},{"id":25,"code":"P.5","type":"MCMA","stem":"Pada kelas RPL dengan komputer terbatas, guru menerapkan proyek inventaris. Tindakan yang mempertahankan substansi belajar adalah ... Pilih semua.","options":["Membagi peran perancang ERD, penulis SQL, dan penguji dengan rotasi.","Menilai hanya keberhasilan mengetik tercepat.","Menyediakan contoh data kecil untuk menguji PK/FK.","Mengadakan presentasi alasan desain yang dapat diikuti anggota tanpa perangkat.","Membiarkan murid yang tak mendapat komputer tidak mengerjakan apa pun."],"key":["A","C","D"],"why":"Peran rotasi, data uji, dan pertanggungjawaban desain memberi kontribusi nyata bagi seluruh murid.","section":"PCK"},{"id":26,"code":"P.5","type":"PG","stem":"Kelompok hendak memakai data asli pelanggan usaha keluarga siswa untuk praktik. Respons paling tepat adalah ...","options":["Menggunakan semua nomor telepon asli agar realistis.","Membuat data simulasi/anonym dan mempertahankan struktur kebutuhan usaha, sambil menjelaskan perlindungan data pribadi.","Membagikan data ke seluruh sekolah.","Menghapus semua konteks usaha dari pembelajaran."],"key":"B","why":"Kasus lokal tetap dapat dipakai tanpa membuka data pribadi; tujuan pembelajaran terletak pada model dan logika data.","section":"PCK"},{"id":27,"code":"P.6","type":"PG","stem":"Sebelum mengajar PK dan FK, guru bertanya apakah dua orang boleh memiliki nama sama dan apakah dua peminjaman bisa dilakukan satu siswa. Fungsi utama pertanyaan itu ialah ...","options":["Asesmen diagnostik untuk memetakan gagasan awal tentang identitas dan relasi.","Penilaian akhir yang langsung menentukan nilai rapor.","Menguji hafalan seluruh sintaks SQL lanjutan.","Menentukan murid mana yang tidak boleh praktik."],"key":"A","why":"Pertanyaan sebelum pembelajaran memunculkan konsepsi awal dan membantu memilih dukungan belajar.","section":"PCK"},{"id":28,"code":"P.6","type":"MCMA","stem":"Murid menghasilkan query JOIN tetapi sebagian rekaman hilang. Bukti asesmen formatif apa yang membantu guru menemukan sumber masalah? Pilih semua.","options":["Meminta murid menjelaskan tabel mana yang menjadi asal setiap kolom.","Mencatat hanya waktu tercepat menjalankan query.","Meminta prediksi baris yang seharusnya muncul dan membandingkannya dengan hasil.","Memeriksa apakah kondisi JOIN dan data kunci cocok.","Memberikan nilai nol sebelum mengetahui alasan kesalahan."],"key":["A","C","D"],"why":"Penelusuran asal kolom, prediksi data, dan pemeriksaan kondisi JOIN menunjukkan miskonsepsi secara spesifik.","section":"PCK"},{"id":29,"code":"P.6","type":"Kategori","stem":"Guru membuat rubrik tugas ERD. Nilai pernyataan berikut sebagai Tepat atau Tidak tepat.","options":["Kriteria mencakup kecocokan entitas, PK, kardinalitas, dan alasan hubungan dengan kasus.","Penilaian hanya berdasarkan warna dan kerapian gambar, tanpa memeriksa kebenaran model.","Guru menjelaskan rubrik sebelum bekerja sehingga murid dapat menggunakannya untuk revisi."],"key":["T","F","T"],"why":"Rubrik selaras dengan tujuan belajar dan transparan sejak awal. Tampilan boleh dipertimbangkan, tetapi bukan inti kompetensi ERD.","section":"PCK"},{"id":30,"code":"P.6","type":"PG","stem":"Murid menggambar relasi siswa–peminjaman sebagai 1:1 padahal satu siswa dapat meminjam berkali-kali. Umpan balik yang paling berguna adalah ...","options":["“Salah semua, ulang dari awal.”","“Bagus, yang penting garisnya lurus.”","“Coba uji kasus satu siswa dengan tiga transaksi. Apakah rancanganmu masih menampung semuanya? Perbaiki kardinalitasnya.”","“Ikuti gambar kelompok lain tanpa bertanya.”"],"key":"C","why":"Umpan balik spesifik memicu pengujian model terhadap kasus sehingga siswa memahami alasan perbaikan.","section":"PCK"},{"id":31,"code":"P.6","type":"PG","stem":"Setelah kuis JOIN, 70% murid salah membedakan INNER dan LEFT JOIN. Langkah selanjutnya paling tepat adalah ...","options":["Melanjutkan bab baru karena rencana sudah ditulis.","Mengelompokkan tipe kesalahan, mengajar ulang dengan data kecil yang punya baris tanpa pasangan, lalu mengecek ulang pemahaman.","Menaikkan nilai agar semua terlihat berhasil.","Memberikan tugas menyalin sintaks tanpa analisis kesalahan."],"key":"B","why":"Hasil asesmen harus dipakai untuk mengubah pengajaran. Data tanpa pasangan memberi bukti konkret perbedaan jenis JOIN.","section":"PCK"},{"id":32,"code":"P.6","type":"MCMA","stem":"Untuk menilai kompetensi implementasi relasi basis data, bukti yang relevan adalah ... Pilih semua.","options":["Skrip pembuatan tabel lengkap dengan PK dan FK yang valid.","Screenshot editor kosong yang rapi.","Data uji yang membuktikan relasi dan penjelasan hasil query.","Uraian alasan memilih kardinalitas dari kebutuhan kasus.","Jumlah ikon pada halaman presentasi."],"key":["A","C","D"],"why":"Bukti autentik harus mencakup artefak teknis, uji perilaku, dan justifikasi rancangan.","section":"PCK"},{"id":33,"code":"P.6","type":"PG","stem":"Tujuan pembelajaran adalah “murid mampu menentukan primary key yang tepat dalam kasus pencatatan data”. Bentuk asesmen paling selaras adalah ...","options":["Menghafalkan sejarah SQL.","Menggambar ikon database.","Menyalin definisi entitas dari modul.","Memilih dan membenarkan PK pada dua kasus dengan nama/atribut yang berpotensi sama."],"key":"D","why":"Tugas memilih dan menjelaskan PK mengukur keputusan teknis sesuai tujuan, bukan hafalan lepas konteks.","section":"PCK"},{"id":34,"code":"P.6","type":"Kategori","stem":"Nilai tindakan umpan balik berikut sebagai Tepat atau Tidak tepat.","options":["Guru menyebut bagian query yang sudah benar dan memberi petunjuk pada kondisi yang perlu diperiksa.","Guru mempublikasikan peringkat murid paling banyak salah untuk mempermalukan mereka.","Guru meminta murid memperbaiki hasilnya lalu menjelaskan perubahan dan alasan revisi."],"key":["T","F","T"],"why":"Umpan balik harus spesifik, aman, dan dapat ditindaklanjuti; revisi menunjukkan belajar dari asesmen.","section":"PCK"},{"id":35,"code":"PF.1","type":"PG","stem":"Pembelajaran proyek aplikasi sekolah dianggap selesai jika website bisa dibuka. Agar tujuan pendidikan kejuruan tercapai lebih utuh, guru seharusnya juga ...","options":["Memastikan murid dapat menjelaskan keputusan, bekerja bertanggung jawab, mengevaluasi keamanan, dan menerima umpan balik pengguna.","Menilai estetika saja.","Membatasi murid pada meniru tampilan tanpa memahami kebutuhan.","Mengutamakan ranking kecepatan mengetik."],"key":"A","why":"Kompetensi SMK mengaitkan penguasaan teknis, penalaran, kerja sama, etika, dan kemampuan beradaptasi.","section":"PCK"},{"id":36,"code":"PF.1","type":"Kategori","stem":"Proyek pembuatan sistem kelas dilakukan dalam pembelajaran. Nilai pernyataan sebagai Tepat atau Tidak tepat.","options":["Mengajak murid membahas hak akses dan dampak aplikasi terhadap pengguna.","Menganggap keberhasilan teknis membenarkan pengumpulan data pribadi berlebihan.","Mengaitkan kemampuan pemrograman dengan penyelesaian masalah nyata dan tanggung jawab sosial."],"key":["T","F","T"],"why":"Tujuan pendidikan menuntut kompetensi dan karakter; etika digital tidak boleh dikorbankan demi fitur.","section":"PCK"},{"id":37,"code":"PF.2","type":"PG","stem":"Saat mengajar keamanan aplikasi, murid membangun query dengan menggabungkan input pengguna ke string SQL. Penjelasan dan perbaikan yang tepat adalah ...","options":["Mengajarkan penggunaan prepared statement/parameter binding dan menunjukkan mengapa input tidak boleh diperlakukan sebagai bagian sintaks SQL.","Memakai kata sandi yang sama untuk semua akun agar mudah.","Menganggap input hanya angka sehingga selalu aman.","Menyembunyikan error tanpa memperbaiki query."],"key":"A","why":"Parameter binding memisahkan data input dari struktur perintah SQL, sehingga efektif menjadi contoh konsep keamanan aplikasi.","section":"PCK"},{"id":38,"code":"PF.2","type":"MCMA","stem":"Murid mendesain tabel siswa dan peminjaman dengan relasi 1:N. Manakah rancangan/aktivitas teknis yang benar? Pilih semua.","options":["Kolom id_siswa dapat menjadi PK di tabel siswa.","Memakai nama_siswa sebagai satu-satunya pengenal karena pasti unik.","Kolom id_siswa di peminjaman dapat menjadi FK menuju siswa.","Menguji apakah sistem menolak peminjaman dengan id_siswa yang tidak ada jika constraint FK aktif.","Satu baris siswa harus digandakan untuk setiap peminjaman."],"key":["A","C","D"],"why":"PK unik di tabel siswa, FK di sisi banyak, dan pengujian integritas merepresentasikan relasi 1:N yang benar.","section":"PCK"},{"id":39,"code":"PF.2","type":"PG","stem":"Murid mengirim form Laravel dengan method POST, tetapi route hanya didaftarkan untuk GET. Strategi pembelajaran tepat adalah ...","options":["Meminta murid me-restart komputer berulang kali.","Mengganti seluruh proyek dengan HTML statis.","Menelusuri alur request dari form ke route dan controller, membandingkan method, lalu memperbaiki definisi route.","Menghapus semua validasi agar request diproses."],"key":"C","why":"Kesalahan method menjadi kesempatan memeriksa hubungan form, HTTP method, route, dan controller.","section":"PCK"},{"id":40,"code":"PF.2","type":"Kategori","stem":"Guru memakai contoh tabel siswa (S1, S2) dan peminjaman (hanya milik S1). Nilai pernyataan konsep SQL sebagai Tepat atau Tidak tepat.","options":["INNER JOIN pada kunci siswa hanya mengembalikan pasangan yang cocok dalam contoh ini.","LEFT JOIN dari tabel siswa ke peminjaman dapat tetap memunculkan S2 dengan kolom peminjaman bernilai NULL.","Setiap LEFT JOIN selalu memiliki jumlah baris tepat sama dengan tabel kiri meski ada beberapa pasangan."],"key":["T","T","F"],"why":"INNER JOIN memerlukan pasangan; LEFT JOIN mempertahankan baris kiri, tetapi bisa menghasilkan lebih banyak baris jika satu baris kiri memiliki banyak pasangan.","section":"PCK"},{"id":41,"code":"PF.2","type":"PG","stem":"Murid membuat kondisi “nilai >= 75” untuk menentukan tuntas. Saat nilai tepat 75, program menyatakan tuntas. Untuk menguji pemahaman kondisi batas, guru sebaiknya meminta ...","options":["Hanya menjalankan input 90 berulang kali.","Menguji nilai 74, 75, 76, lalu menjelaskan fungsi operator >= terhadap ketiga hasil.","Mengganti semua operator menjadi ==.","Menilai warna tombol terlebih dahulu."],"key":"B","why":"Kasus batas 74, 75, 76 secara langsung menampakkan efek operator perbandingan.","section":"PCK"},{"id":42,"code":"PF.2","type":"MCMA","stem":"Untuk membimbing praktik Git yang dapat dipertanggungjawabkan, guru mengutamakan ... Pilih semua.","options":["Commit perubahan kecil dengan pesan bermakna.","Menyimpan kata sandi ke repositori publik supaya semua bisa uji.","Menggunakan pull request/review perubahan untuk proyek kolaboratif.","Menangani konflik penggabungan dengan membaca perubahan yang bertentangan.","Menghapus riwayat agar kontribusi tidak terlihat."],"key":["A","C","D"],"why":"Praktik version control mencakup jejak perubahan, review, dan resolusi konflik. Kredensial tidak boleh dipublikasikan.","section":"PCK"},{"id":43,"code":"PF.3","type":"PG","stem":"Sebagian siswa memahami logika program tetapi kesulitan membaca instruksi teks panjang. Guru ingin mengukur logika seleksi kondisi. Penyesuaian terbaik adalah ...","options":["Memberi diagram alir sederhana dan contoh input-output, lalu meminta siswa menjelaskan atau mengimplementasikan logika yang sama.","Mengganti semua kompetensi menjadi hafalan istilah.","Menganggap kesulitan membaca berarti tidak mampu pemrograman.","Menilai kualitas tulisan tangan sebagai kompetensi inti."],"key":"A","why":"Representasi visual dan contoh mengurangi hambatan bahasa tanpa menghilangkan tuntutan logika seleksi.","section":"PCK"},{"id":44,"code":"PF.3","type":"MCMA","stem":"Guru menggunakan kasus katalog produk UMKM setempat untuk basis data kelas. Praktik yang tepat adalah ... Pilih semua.","options":["Menyusun dataset tiruan yang menjaga struktur produk-kategori-transaksi.","Mengharuskan semua murid memiliki pengalaman usaha keluarga.","Memberikan penjelasan istilah yang belum dikenal murid.","Membuka alternatif kasus sepadan bagi murid yang lebih memahami perpustakaan atau inventaris.","Memakai informasi kontak pelanggan asli tanpa izin."],"key":["A","C","D"],"why":"Kasus lokal relevan dengan dukungan bahasa, pilihan konteks setara, dan perlindungan privasi.","section":"PCK"},{"id":45,"code":"PF.3","type":"Kategori","stem":"Untuk menetapkan kesiapan kelas sebelum materi API, nilai tindakan berikut sebagai Tepat atau Tidak tepat.","options":["Memeriksa apakah murid sudah memahami request, response, dan format data sederhana.","Menganggap semua murid otomatis memahami API karena sering memakai aplikasi.","Menyiapkan contoh konkret JSON dan alur pertukaran data bagi yang membutuhkan."],"key":["T","F","T"],"why":"Membaca kebutuhan berdasarkan prasyarat nyata, bukan asumsi kebiasaan memakai teknologi.","section":"PCK"},{"id":46,"code":"PF.4","type":"PG","stem":"Sekolah perlu mengontekstualkan pembelajaran RPL dengan kebutuhan inventaris. Guru sedang menyusun alur tujuan pembelajaran. Pilihan terbaik adalah ...","options":["Mengganti seluruh capaian menjadi dekorasi website karena paling disukai murid.","Memilih aktivitas populer tanpa menghubungkan ke tujuan.","Menetapkan tujuan kompetensi terkait analisis kebutuhan, model data, dan pengujian; kasus inventaris menjadi konteks pencapaiannya.","Menyamakan semua murid tanpa mempertimbangkan pengetahuan awal."],"key":"C","why":"Adaptasi kurikulum tetap menurunkan tujuan dari capaian dan memilih konteks untuk mencapainya.","section":"PCK"},{"id":47,"code":"PF.4","type":"MCMA","stem":"Framework web berubah versi. Guru ingin materi tetap relevan secara kurikuler. Mana yang tepat? Pilih semua.","options":["Mempertahankan prinsip request-response, validasi, dan pengelolaan data sebagai konsep lintas-versi.","Mewajibkan murid menghafal seluruh sintaks versi lama tanpa memahami konsep.","Memperbarui contoh sesuai dokumentasi tepercaya sambil menguji kompatibilitas.","Membandingkan perubahan sintaks dengan prinsip yang tetap berlaku.","Menghapus semua pelajaran dasar karena framework akan selalu berubah."],"key":["A","C","D"],"why":"Kurikulum adaptif memperbarui contoh tanpa mengorbankan konsep fundamental serta tujuan kompetensi.","section":"PCK"},{"id":48,"code":"PF.4","type":"Kategori","stem":"Guru menyelaraskan tujuan, kegiatan, dan asesmen untuk materi ERD. Nilai berikut sebagai Tepat atau Tidak tepat.","options":["Jika tujuan menentukan kardinalitas, siswa diberi kasus untuk menjelaskan arah relasi dan jumlah keterlibatan entitas.","Jika tujuan merancang ERD, tes satu-satunya harus menanyakan warna simbol pada aplikasi gambar tertentu.","Rubrik menyebut indikator kebenaran entitas, hubungan, dan alasan model."],"key":["T","F","T"],"why":"Keselarasan capaian–aktivitas–asesmen lebih penting daripada fitur alat tertentu.","section":"PCK"},{"id":49,"code":"PF.5","type":"PG","stem":"Guru mencatat bahwa murid berulang kali salah menentukan foreign key walau sudah diberi penjelasan. Tindakan pengembangan praktik paling ilmiah adalah ...","options":["Menganggap murid malas dan mempertahankan pendekatan yang sama.","Mencoba intervensi contoh data berelasi, membandingkan bukti kerja sebelum-sesudah, lalu merefleksikan hasilnya.","Memilih intervensi baru hanya karena sedang viral.","Mengurangi target asesmen agar tampak berhasil."],"key":"B","why":"Perbaikan profesional bertumpu pada identifikasi masalah, tindakan beralasan, bukti hasil, dan refleksi.","section":"PCK"},{"id":50,"code":"PF.5","type":"MCMA","stem":"Setelah proyek website, guru mengembangkan praktik melalui komunitas guru RPL. Tindakan yang etis dan bermanfaat adalah ... Pilih semua.","options":["Membagikan contoh rubrik dan data hasil belajar yang telah dianonimkan untuk mendapat masukan.","Menyebarkan nilai beserta nomor telepon siswa kepada publik.","Menguji masukan rekan pada kelas dan mengamati dampaknya.","Mendokumentasikan keterbatasan uji coba agar tidak mengklaim pasti berhasil.","Mengklaim satu percobaan kecil membuktikan semua metode lain salah."],"key":["A","C","D"],"why":"Pengembangan praktik harus reflektif, terbuka pada bukti, dan melindungi identitas murid.","section":"PCK"},{"id":51,"code":"P.1","type":"PG","stem":"Guru IPS ingin siswa memahami perubahan lingkungan, menerapkan konsep pada lingkungan sekitar, lalu merefleksikan pilihan tindakannya. Rancangan terbaik adalah ...","options":["Ceramah definisi lalu tes hafalan semata.","Kuis cepat tanpa kegiatan lanjutan.","Mengamati masalah sekitar, menganalisis dengan konsep yang dipelajari, mengusulkan langkah, dan menulis refleksi.","Meminta menyalin isi buku tanpa diskusi."],"key":"C","why":"Rancangan ini menyatukan pemahaman konsep, penerapan kontekstual, dan refleksi bermakna sebagaimana P.1.","section":"PU"},{"id":52,"code":"P.1","type":"Kategori","stem":"Nilai langkah pembelajaran bermakna berikut sebagai Tepat atau Tidak tepat.","options":["Membuka ruang bagi siswa menjelaskan apa yang berubah dari pemahaman awalnya.","Membatasi keberhasilan pada selesai menyalin jawaban guru.","Menautkan kegiatan dengan tujuan yang jelas dan tantangan di kehidupan nyata."],"key":["T","F","T"],"why":"Refleksi dan transfer menunjukkan pemahaman; reproduksi jawaban saja belum cukup.","section":"PU"},{"id":53,"code":"P.1","type":"MCMA","stem":"Guru menemukan miskonsepsi pada konsep yang menjadi prasyarat pelajaran berikutnya. Strategi yang tepat adalah ... Pilih semua.","options":["Mengumpulkan jawaban awal untuk mengetahui penalaran siswa.","Memberi contoh pembanding yang menguji gagasan keliru.","Menolak pertanyaan karena mengganggu jadwal.","Meminta siswa membandingkan gagasan awal dan hasil setelah eksplorasi.","Memberi nilai akhir hanya dari kecepatan menjawab."],"key":["A","B","D"],"why":"Perubahan konsep dibantu diagnosis, bukti pembanding, dan refleksi pemahaman.","section":"PU"},{"id":54,"code":"P.2","type":"PG","stem":"Dalam satu kelas ada siswa dengan kemampuan membaca berbeda. Guru ingin semua memahami gagasan utama bacaan. Pilihan terbaik adalah ...","options":["Memakai satu bahan sulit tanpa dukungan karena adil artinya sama persis.","Menyediakan teks inti, penjelasan visual/audio yang relevan, dan pertanyaan tujuan sama dengan dukungan berbeda.","Mengeluarkan siswa yang lambat dari kegiatan.","Menggantikan tujuan memahami bacaan menjadi sekadar kehadiran."],"key":"B","why":"Kesetaraan tujuan dapat disertai variasi dukungan agar hambatan akses tidak menghalangi pencapaian.","section":"PU"},{"id":55,"code":"P.2","type":"Kategori","stem":"Kelas terdiri atas siswa dari beragam latar bahasa. Nilai tindakan berikut sebagai Tepat atau Tidak tepat.","options":["Guru memastikan istilah penting dipahami melalui contoh tanpa merendahkan bahasa rumah siswa.","Guru menganggap aksen berbeda sebagai tanda kemampuan berpikir rendah.","Guru memberi kesempatan murid mengungkapkan ide secara bertahap dengan dukungan bahasa."],"key":["T","F","T"],"why":"Pembelajaran responsif menghargai identitas bahasa sekaligus menjaga target akademik.","section":"PU"},{"id":56,"code":"P.2","type":"MCMA","stem":"Guru mengatur kerja kelompok dengan siswa yang berbeda kesiapan dan kebutuhan. Pilih keputusan yang tepat.","options":["Membagikan peran jelas dan kesempatan rotasi peran.","Menyerahkan semua pekerjaan ke satu siswa yang dianggap pintar.","Mengecek secara berkala siapa yang belum mendapat kesempatan bicara.","Menyediakan kriteria tugas dan bantuan berjenjang.","Memberi label permanen kelompok pintar dan lemah."],"key":["A","C","D"],"why":"Peran, pemantauan partisipasi, dan scaffolding mendukung keterlibatan seluruh siswa.","section":"PU"},{"id":57,"code":"P.2","type":"PG","stem":"Siswa pindahan belum mengenal istilah teknis yang telah dipelajari kelas. Langkah awal paling tepat adalah ...","options":["Menganggap ia tertinggal permanen.","Memberi ujian dengan skor nol lalu mengumumkannya.","Mewajibkan menghafal semua istilah dalam satu malam.","Memeriksa prasyarat, memberi glosarium/contoh ringkas, dan memasangkan dukungan belajar tanpa mengurangi tujuan."],"key":"D","why":"Dukungan spesifik berdasarkan prasyarat lebih efektif daripada stigma atau tuntutan tanpa bantuan.","section":"PU"},{"id":58,"code":"P.3","type":"PG","stem":"Seorang siswa memberi jawaban salah dan beberapa teman tertawa. Guru sebaiknya ...","options":["Mengajak kelas menghargai proses mencoba, menanyakan alasan jawaban, dan menuntun peninjauan bukti tanpa mempermalukan.","Membiarkan ejekan demi kebebasan berekspresi.","Langsung menghapus nilai siswa yang salah.","Membuat daftar siswa yang tidak boleh menjawab lagi."],"key":"A","why":"Keamanan psikologis dan pembahasan alasan menciptakan ruang belajar yang berkesadaran dan menggembirakan.","section":"PU"},{"id":59,"code":"P.3","type":"Kategori","stem":"Nilai gagasan tentang pembelajaran berkesadaran, bermakna, dan menggembirakan berikut sebagai Tepat atau Tidak tepat.","options":["Siswa memahami tujuan belajar dan diberi ruang merefleksikan prosesnya.","Pembelajaran menggembirakan selalu berarti tanpa tantangan akademik.","Aktivitas boleh menantang apabila ada dukungan, relevansi, dan suasana aman."],"key":["T","F","T"],"why":"Kegembiraan belajar bukan hiburan semata; fokus, relevansi, tantangan yang terdukung, dan rasa aman bisa berjalan bersama.","section":"PU"},{"id":60,"code":"P.4","type":"PG","stem":"Guru ingin siswa memakai AI untuk membuat rangkuman materi. Risiko utamanya ialah jawaban AI bisa keliru dan data siswa dapat terbuka. Langkah tepat adalah ...","options":["Mewajibkan semua siswa mengunggah informasi keluarga.","Mengevaluasi keluaran dengan sumber tepercaya, melarang pengiriman data pribadi, dan meminta siswa menjelaskan hasil dengan bahasa sendiri.","Melarang semua diskusi literasi digital.","Menganggap keluaran AI otomatis bersumber resmi."],"key":"B","why":"Literasi digital meliputi verifikasi dan privasi, bukan hanya kemampuan menjalankan alat.","section":"PU"},{"id":61,"code":"P.4","type":"MCMA","stem":"Guru memilih media pembelajaran digital untuk kelas dengan akses beragam. Pertimbangan yang tepat adalah ... Pilih semua.","options":["Tersedia versi berukuran ringan atau alternatif luring.","Tampilan dan petunjuk mudah diakses dengan kebutuhan murid yang beragam.","Selalu mewajibkan gawai spesifikasi tinggi walau banyak murid tidak memiliki.","Data murid yang diperlukan dibatasi sesuai tujuan.","Memilih media hanya karena sedang populer."],"key":["A","B","D"],"why":"Akses, inklusi, dan keamanan data menjadi dasar pemilihan TIK yang kritis.","section":"PU"},{"id":62,"code":"P.5","type":"PG","stem":"Guru akan mengajar perbandingan dengan contoh kehidupan sekitar. Sebagian siswa belum familiar dengan konteks pasar tradisional. Pilihan terbaik adalah ...","options":["Memakai hanya satu contoh dan menyalahkan yang tidak paham.","Menghindari konteks nyata sama sekali.","Menyediakan beberapa konteks setara yang familier dan mengajak siswa menghubungkan ke konsep yang sama.","Menilai latar budaya sebagai faktor kemampuan permanen."],"key":"C","why":"Konteks beragam membantu transfer konsep tanpa mengasumsikan pengalaman semua siswa identik.","section":"PU"},{"id":63,"code":"P.5","type":"Kategori","stem":"Nilai pilihan sumber belajar berikut sebagai Tepat atau Tidak tepat.","options":["Sumber lokal dipilih karena membantu mencapai tujuan dan dapat diakses murid.","Contoh lokal harus selalu dipakai meskipun menimbulkan stereotip kelompok tertentu.","Guru memeriksa kesesuaian isi sumber dengan tingkat kesiapan murid."],"key":["T","F","T"],"why":"Kontekstual bukan otomatis baik; guru perlu menjaga relevansi, akurasi, dan penghargaan pada keragaman.","section":"PU"},{"id":64,"code":"P.6","type":"PG","stem":"Di awal topik pecahan, guru memberi dua soal singkat untuk melihat apakah siswa memahami bagian dari keseluruhan. Informasi ini paling tepat dipakai untuk ...","options":["Menentukan dukungan, contoh, dan kelompok fleksibel sebelum pembelajaran inti.","Menghukum murid yang jawabannya salah.","Menetapkan nilai rapor tanpa pembelajaran.","Mengabaikan hasil karena baru asesmen awal."],"key":"A","why":"Asesmen awal dipakai untuk mengidentifikasi kebutuhan belajar, bukan memberi label atau hukuman.","section":"PU"},{"id":65,"code":"P.6","type":"MCMA","stem":"Setelah exit ticket, guru mengetahui separuh kelas masih bingung menentukan alasan jawaban. Langkah tepat adalah ... Pilih semua.","options":["Mengelompokkan jawaban untuk mengidentifikasi pola kesalahan.","Memberi penjelasan/model tambahan yang menanggapi pola tersebut.","Mengajak siswa mengerjakan soal cek singkat untuk memastikan perbaikan.","Mengabaikan hasil karena materi sudah selesai diajarkan.","Mempermalukan siswa yang jawabannya belum tepat."],"key":["A","B","C"],"why":"Asesmen formatif bermakna jika hasilnya ditafsirkan dan digunakan untuk memperbaiki proses serta mengecek dampaknya.","section":"PU"},{"id":66,"code":"P.6","type":"Kategori","stem":"Nilai contoh umpan balik berikut sebagai Tepat atau Tidak tepat.","options":["“Alasanmu sudah menyebut dua bukti; cek lagi apakah bukti ketiga mendukung simpulanmu.”","“Kamu memang tidak berbakat; jangan mencoba soal ini lagi.”","“Bandingkan jawabanmu dengan rubrik, revisi satu bagian, lalu jelaskan mengapa diubah.”"],"key":["T","F","T"],"why":"Umpan balik yang baik spesifik, menjaga martabat, dan menyebut langkah perbaikan yang dapat dilakukan.","section":"PU"},{"id":67,"code":"P.6","type":"PG","stem":"Hasil penilaian akhir memperlihatkan banyak siswa belum mencapai satu indikator. Tindakan guru berikutnya yang paling bertanggung jawab adalah ...","options":["Menganggap tugas selesai karena nilai sudah terbit.","Membuat semua soal berikutnya lebih mudah tanpa pembelajaran.","Menyembunyikan hasil dari siswa.","Menganalisis indikator yang lemah, merancang tindak lanjut sesuai kebutuhan, serta mengomunikasikan kesempatan perbaikan."],"key":"D","why":"Hasil asesmen digunakan untuk keputusan pembelajaran dan tindak lanjut, bukan sekadar angka akhir.","section":"PU"},{"id":68,"code":"K.1","type":"PG","stem":"Seorang murid menceritakan sedang mengalami masalah keluarga dan meminta tidak diumumkan. Respons guru yang paling etis adalah ...","options":["Menjadikan cerita sebagai contoh di depan kelas dengan nama lengkap.","Mendengarkan secara empatik, menjaga kerahasiaan sesuai kewajiban perlindungan murid, dan merujuk ke pihak yang berwenang bila ada risiko keselamatan.","Menyebarkannya di grup guru tanpa pertimbangan.","Mengabaikan seluruh informasi meski ada tanda bahaya."],"key":"B","why":"Etika menuntut empati dan privasi; jika terdapat risiko keselamatan, guru mengikuti prosedur perlindungan dan rujukan yang tepat.","section":"PU"},{"id":69,"code":"K.1","type":"Kategori","stem":"Nilai perilaku guru berikut sebagai Tepat atau Tidak tepat.","options":["Guru menyampaikan kriteria penilaian sebelum tugas dan menerapkannya konsisten.","Guru menaikkan nilai murid tertentu karena kedekatan pribadi tanpa bukti belajar.","Guru mengakui kekeliruan penjelasannya lalu memperbaiki di depan kelas secara profesional."],"key":["T","F","T"],"why":"Keteladanan ditunjukkan oleh keadilan, integritas, dan tanggung jawab memperbaiki kesalahan.","section":"PU"},{"id":70,"code":"K.2","type":"PG","stem":"Setelah proyek kelompok gagal mencapai target, guru merasa metode yang dipilih tidak efektif. Refleksi profesional paling tepat adalah ...","options":["Menyalahkan sepenuhnya karakter murid.","Mengulangi tugas sama tanpa perubahan.","Meninjau bukti aktivitas dan hasil, meminta umpan balik murid, lalu menetapkan perbaikan yang bisa diuji.","Berhenti mencoba pembelajaran kolaboratif selamanya."],"key":"C","why":"Refleksi diri berbasis bukti mendukung pola pikir bertumbuh dan peningkatan praktik.","section":"PU"},{"id":71,"code":"K.2","type":"MCMA","stem":"Guru ingin mengembangkan kompetensi secara berkelanjutan. Mana yang mencerminkan growth mindset profesional? Pilih semua.","options":["Mencatat satu aspek pembelajaran yang perlu diperbaiki dari umpan balik.","Mencoba strategi baru secara terukur dan membandingkan buktinya.","Menganggap kritik berarti dirinya bukan guru yang baik sehingga menolak masukan.","Berdiskusi dengan rekan dan menyesuaikan praktik dari temuan.","Mengklaim dirinya sudah tidak perlu belajar karena telah lulus pendidikan guru."],"key":["A","B","D"],"why":"Pola pikir bertumbuh tampak dalam penerimaan masukan, eksperimen terukur, dan tindak lanjut hasil refleksi.","section":"PU"},{"id":72,"code":"K.3","type":"PG","stem":"Dalam diskusi kelas, hanya beberapa siswa berani berbicara. Guru ingin membangun budaya belajar saling mendukung. Langkah terbaik adalah ...","options":["Memberi label murid pendiam sebagai tidak aktif.","Memanggil siswa acak lalu mempermalukannya jika belum siap.","Mengizinkan siswa dominan berbicara sepanjang waktu.","Menyepakati aturan diskusi, memberi waktu berpikir, dan memakai giliran berbagi yang aman serta adil."],"key":"D","why":"Keputusan guru perlu konsisten membangun partisipasi dan rasa aman untuk mengembangkan potensi semua murid.","section":"PU"},{"id":73,"code":"K.3","type":"Kategori","stem":"Nilai keputusan pembentukan budaya belajar berikut sebagai Tepat atau Tidak tepat.","options":["Guru menegaskan bahwa semua siswa dapat berkembang melalui latihan dan umpan balik.","Guru menjadikan ranking publik sebagai identitas kemampuan yang tidak dapat berubah.","Guru memberi kesempatan revisi tugas berdasarkan kriteria yang jelas."],"key":["T","F","T"],"why":"Budaya belajar positif menekankan perkembangan, standar yang jelas, dan peluang belajar dari kesalahan.","section":"PU"},{"id":74,"code":"S.1","type":"PG","stem":"Orang tua menghubungi guru karena anaknya merasa tidak dipahami di kelas. Respons komunikasi paling tepat adalah ...","options":["Menjawab defensif bahwa guru selalu benar.","Mendengarkan kekhawatiran, menggali contoh konkret, menjelaskan temuan tanpa menyalahkan, lalu menyepakati tindak lanjut.","Mengunggah percakapan ke media sosial.","Menilai anak hanya dari komentar orang tua tanpa observasi."],"key":"B","why":"Komunikasi inklusif dan empatik mencari pemahaman bersama dan tindakan yang berbasis informasi.","section":"PU"},{"id":75,"code":"S.1","type":"MCMA","stem":"Guru memberi umpan balik kepada siswa yang berbeda latar bahasa dan gaya komunikasi. Cara yang tepat adalah ... Pilih semua.","options":["Menggunakan kalimat jelas dan contoh spesifik.","Memastikan siswa memahami tindak lanjut dengan kesempatan bertanya.","Mengejek pengucapan bahasa siswa.","Menyediakan saluran tertulis/visual bila membantu komunikasi.","Memotong penjelasan siswa karena lambat menyampaikan ide."],"key":["A","B","D"],"why":"Umpan balik inklusif menyesuaikan cara komunikasi sambil menghargai martabat dan kebutuhan murid.","section":"PU"},{"id":76,"code":"S.2","type":"PG","stem":"Seorang siswa sering absen sehingga tertinggal tugas. Guru mata pelajaran belum memahami penyebabnya. Langkah kolaboratif paling tepat adalah ...","options":["Menyimpulkan bahwa orang tua tidak peduli.","Mengumumkan identitas dan masalah siswa pada publik.","Berkoordinasi dengan wali kelas/BK secara proporsional, mendengar siswa dan keluarga, serta menyusun dukungan belajar.","Memberi nilai nol permanen tanpa mencari informasi."],"key":"C","why":"Kolaborasi dengan pihak terkait memetakan hambatan dan merancang dukungan, tetap menjaga privasi.","section":"PU"},{"id":77,"code":"S.2","type":"Kategori","stem":"Nilai tindakan kolaborasi sekolah–orang tua berikut sebagai Tepat atau Tidak tepat.","options":["Guru berbagi perkembangan belajar yang relevan melalui jalur komunikasi yang tepat.","Guru menyebarkan data pribadi murid kepada semua orang tua agar transparan.","Guru melibatkan pihak sekolah sesuai kewenangan saat merancang tindak lanjut kebutuhan murid."],"key":["T","F","T"],"why":"Kolaborasi memerlukan komunikasi terarah dan perlindungan kerahasiaan data murid.","section":"PU"},{"id":78,"code":"S.3","type":"PG","stem":"Komunitas guru membahas cara meningkatkan keterlibatan siswa dalam diskusi. Kontribusi paling bermanfaat adalah ...","options":["Berbagi praktik beserta bukti, mendengarkan masukan rekan, dan mencoba perbaikan yang sesuai konteks kelas.","Mengirim materi orang lain tanpa atribusi dan mengklaim hasilnya.","Menganggap semua strategi pasti cocok di semua sekolah.","Hanya meminta sertifikat tanpa mengikuti diskusi."],"key":"A","why":"Komunitas pembelajaran berguna ketika praktik, bukti, dan refleksi dibagikan secara bertanggung jawab.","section":"PU"},{"id":79,"code":"PF.1","type":"PG","stem":"Guru menilai proyek lintas mata pelajaran. Hasil belajar paling menggambarkan tujuan pendidikan yang luas adalah ...","options":["Siswa hanya meniru jawaban tanpa memahami alasannya.","Siswa hanya memperoleh angka ujian yang tinggi.","Siswa menyelesaikan tugas cepat tetapi menolak berdiskusi.","Siswa mampu menjelaskan penalaran, bekerja sama secara etis, dan menerapkan pengetahuan untuk masalah bermakna."],"key":"D","why":"Tujuan pendidikan mencakup penguasaan pengetahuan, karakter, kolaborasi, dan penerapan yang bertanggung jawab.","section":"PU"},{"id":80,"code":"PF.3","type":"MCMA","stem":"Dalam proyek sains lingkungan, sekolah memiliki keterbatasan alat dan kondisi lingkungan yang berbeda. Adaptasi yang tetap menjaga kompetensi adalah ... Pilih semua.","options":["Menggunakan pengamatan lingkungan setempat dengan prosedur aman dan data yang dapat dicatat.","Menyediakan format pencatatan sederhana dan contoh analisis data.","Menghapus kompetensi analisis karena alat laboratorium terbatas.","Membandingkan hasil dengan konsep ilmiah dan membahas keterbatasan pengamatan.","Memaksakan alat yang tidak aman demi meniru sekolah lain."],"key":["A","B","D"],"why":"Konteks lokal dapat menggantikan media mahal jika tujuan dan penalaran tetap dipertahankan secara aman.","section":"PU"}]};
